/* DAWAH X — ahmad, অধ্যায় 78 · খণ্ড 78 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][78]=[[15401,15401,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْهِرْمَاسُ بْنُ زِيَادٍ الْبَاهِلِيُّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ عَلَى رَاحِلَتِهِ يَوْمَ النَّحْرِ ‏ ‏بِمِنًي ‏","","",""],[15402,15402,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ وَهُوَ الْعِجْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْهِرْمَاسُ بْنُ زِيَادٍ الْبَاهِلِيُّ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رِدْفَ ‏ ‏أَبِي يَوْمَ الْأَضْحَى وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ عَلَى نَاقَتِهِ ‏ ‏بِمِنًى ‏","","",""],[15403,15403,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَاقِدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنِ ‏ ‏الْهِرْمَاسِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى بَعِيرٍ نَحْوَ ‏ ‏الشَّامِ ‏","","",""],[15404,15404,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عِمْرَانَ بْنِ أَبِي عَلِيٍّ أَبُو مُحَمَّدٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الرَّيِّ ‏ ‏وَكَانَ أَصْلُهُ ‏ ‏أَصْبَهَانِيًّا ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ الضُّرَيْسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏هِرْمَاسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رِدْفَ ‏ ‏أَبِي فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَعِيرٍ وَهُوَ يَقُولُ ‏ ‏لَبَّيْكَ بِحَجَّةٍ وَعُمْرَةٍ مَعًا ‏","","",""],[15405,15405,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زُرَارَةَ السَّهْمِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏الْحَارِثِ بْنِ عَمْرٍو ‏ ‏أَنَّهُ لَقِيَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ فَقُلْتُ بِأَبِي أَنْتَ يَا رَسُولَ اللَّهِ اسْتَغْفِرْ لِي قَالَ غَفَرَ اللَّهُ لَكُمْ قَالَ وَهُوَ عَلَى نَاقَتِهِ ‏ ‏الْعَضْبَاءِ ‏ ‏قَالَ فَاسْتَدَرْتُ لَهُ مِنْ الشِّقِّ الْآخَرِ أَرْجُو أَنْ يَخُصَّنِي دُونَ الْقَوْمِ فَقُلْتُ اسْتَغْفِرْ لِي قَالَ غَفَرَ اللَّهُ لَكُمْ قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ ‏ ‏الْفَرَائِعُ ‏ ‏وَالْعَتَائِرُ ‏ ‏قَالَ ‏ ‏مَنْ شَاءَ ‏ ‏فَرَّعَ ‏ ‏وَمَنْ شَاءَ لَمْ ‏ ‏يُفَرِّعْ ‏ ‏وَمَنْ شَاءَ ‏ ‏عَتَرَ ‏ ‏وَمَنْ شَاءَ لَمْ ‏ ‏يَعْتِرْ ‏ ‏فِي الْغَنَمِ أُضْحِيَّةٌ ثُمَّ قَالَ أَلَا إِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ عَلَيْكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ زُرَارَةَ السَّهْمِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏الْحَارِثِ ‏","","",""],[15406,15406,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ عُبَيْدِ بْنِ السَّبَّاقِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ حُنَيْفٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَلْقَى مِنْ ‏ ‏الْمَذْيِ ‏ ‏شِدَّةً فَكُنْتُ أُكْثِرُ ‏ ‏الِاغْتِسَالَ مِنْهُ فَسَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَقَالَ ‏ ‏إِنَّمَا يُجْزِئُكَ مِنْهُ الْوُضُوءُ فَقُلْتُ كَيْفَ بِمَا يُصِيبُ ثَوْبِي فَقَالَ يَكْفِيكَ أَنْ تَأْخُذَ كَفًّا مِنْ مَاءٍ فَتَمْسَحَ بِهَا مِنْ ثَوْبِكَ حَيْثُ ‏ ‏تَرَى أَنَّهُ أَصَابَ ‏","","",""],[15407,15407,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ قَالَ ‏ ‏سَهْلُ بْنُ حُنَيْفٍ ‏ ‏اتَّهِمُوا ‏ ‏رَأْيَكُمْ فَلَقَدْ رَأَيْتُنَا يَوْمَ ‏ ‏أَبِي جَنْدَلٍ ‏ ‏وَلَوْ نَسْتَطِيعُ أَنْ نَرُدَّ أَمْرَهُ لَرَدَدْنَاهُ وَاللَّهِ مَا وَضَعْنَا سُيُوفَنَا عَنْ ‏ ‏عَوَاتِقِنَا ‏ ‏مُنْذُ أَسْلَمْنَا لِأَمْرٍ يُفْظِعُنَا إِلَّا أَسْهَلَ بِنَا إِلَى أَمْرٍ نَعْرِفُهُ إِلَّا هَذَا الْأَمْرَ مَا سَدَدْنَا خَصْمًا إِلَّا انْفَتَحَ لَنَا خَصْمٌ آخَرُ ‏","","",""],[15408,15408,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ سِيَاهٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏فِي مَسْجِدِ أَهْلِهِ أَسْأَلُهُ عَنْ هَؤُلَاءِ الْقَوْمِ الَّذِينَ قَتَلَهُمْ ‏ ‏عَلِيٌّ ‏ ‏بِالنَّهْرَوَانِ ‏ ‏فَفِيمَا اسْتَجَابُوا لَهُ وَفِيمَا فَارَقُوهُ وَفِيمَا اسْتَحَلَّ قِتَالَهُمْ قَالَ كُنَّا ‏ ‏بِصِفِّينَ ‏ ‏فَلَمَّا ‏ ‏اسْتَحَرَّ ‏ ‏الْقَتْلُ بِأَهْلِ ‏ ‏الشَّامِ ‏ ‏اعْتَصَمُوا بِتَلٍّ فَقَالَ ‏ ‏عَمْرُو بْنُ الْعَاصِ ‏ ‏لِمُعَاوِيَةَ ‏ ‏أَرْسِلْ إِلَى ‏ ‏عَلِيٍّ ‏ ‏بِمُصْحَفٍ وَادْعُهُ إِلَى كِتَابِ اللَّهِ فَإِنَّهُ لَنْ ‏ ‏يَأْبَى عَلَيْكَ فَجَاءَ بِهِ رَجُلٌ فَقَالَ بَيْنَنَا وَبَيْنَكُمْ كِتَابُ اللَّهِ ‏ { ‏أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِنْ الْكِتَابِ يُدْعَوْنَ إِلَى كِتَابِ اللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّى فَرِيقٌ مِنْهُمْ وَهُمْ مُعْرِضُونَ ‏} ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏نَعَمْ أَنَا أَوْلَى بِذَلِكَ بَيْنَنَا وَبَيْنَكُمْ كِتَابُ ‏ ‏اللَّهِ قَالَ فَجَاءَتْهُ ‏ ‏الْخَوَارِجُ ‏ ‏وَنَحْنُ ‏ ‏نَدْعُوهُمْ يَوْمَئِذٍ الْقُرَّاءَ وَسُيُوفُهُمْ عَلَى ‏ ‏عَوَاتِقِهِمْ ‏ ‏فَقَالُوا يَا أَمِيرَ الْمُؤْمِنِينَ مَا نَنْتَظِرُ بِهَؤُلَاءِ الْقَوْمِ الَّذِينَ عَلَى التَّلِّ أَلَا نَمْشِي إِلَيْهِمْ بِسُيُوفِنَا حَتَّى يَحْكُمَ اللَّهُ بَيْنَنَا وَبَيْنَهُمْ فَتَكَلَّمَ ‏ ‏سَهْلُ بْنُ حُنَيْفٍ ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏اتَّهِمُوا ‏ ‏أَنْفُسَكُمْ فَلَقَدْ رَأَيْتُنَا يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏يَعْنِي الصُّلْحَ الَّذِي كَانَ بَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ الْمُشْرِكِينَ ‏ ‏وَلَوْ نَرَى قِتَالًا لَقَاتَلْنَا فَجَاءَ ‏ ‏عُمَرُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَلَسْنَا عَلَى الْحَقِّ وَهُمْ عَلَى بَاطِلٍ أَلَيْسَ قَتْلَانَا فِي الْجَنَّةِ وَقَتْلَاهُمْ فِي النَّارِ قَالَ بَلَى قَالَ فَفِيمَ ‏ ‏نُعْطِي ‏ ‏الدَّنِيَّةَ ‏ ‏فِي دِينِنَا وَنَرْجِعُ وَلَمَّا ‏ ‏يَحْكُمِ اللَّهُ بَيْنَنَا وَبَيْنَهُمْ فَقَالَ يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏إِنِّي رَسُولُ اللَّهِ وَلَنْ يُضَيِّعَنِي أَبَدًا قَالَ فَرَجَعَ وَهُوَ مُتَغَيِّظٌ فَلَمْ يَصْبِرْ حَتَّى أَتَى ‏ ‏أَبَا بَكْرٍ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏أَلَسْنَا عَلَى حَقٍّ وَهُمْ عَلَى بَاطِلٍ أَلَيْسَ قَتْلَانَا فِي الْجَنَّةِ وَقَتْلَاهُمْ فِي النَّارِ قَالَ بَلَى قَالَ فَفِيمَ ‏ ‏نُعْطِي ‏ ‏الدَّنِيَّةَ ‏ ‏فِي دِينِنَا وَنَرْجِعُ وَلَمَّا ‏ ‏يَحْكُمِ اللَّهُ بَيْنَنَا وَبَيْنَهُمْ فَقَالَ يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏إِنَّهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَنْ يُضَيِّعَهُ اللَّهُ أَبَدًا قَالَ فَنَزَلَتْ سُورَةُ ‏ ‏الْفَتْحِ ‏ ‏قَالَ فَأَرْسَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏عُمَرَ ‏ ‏فَأَقْرَأَهَا إِيَّاهُ قَالَ يَا رَسُولَ اللَّهِ وَفَتْحٌ هُوَ قَالَ نَعَمْ ‏","","",""],[15409,15409,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏الْعَوَّامُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو إِسْحَاقَ الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏يُسَيْرِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ حُنَيْفٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلِيَّةُ قَوْمٍ قِبَلَ الْمَشْرِقِ مُحَلَّقَةٌ رُءُوسُهُمْ وَسُئِلَ عَنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ حَرَامٌ آمِنٌ حَرَامٌ آمِنٌ ‏","","",""],[15410,15410,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حِزَامُ بْنُ إِسْمَاعِيلَ الْعَامِرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏يُسَيْرِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏سَهْلِ بْنِ حُنَيْفٍ ‏ ‏فَقُلْتُ حَدِّثْنِي مَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي ‏ ‏الْحَرُورِيَّةِ ‏ ‏قَالَ أُحَدِّثُكَ مَا سَمِعْتُ لَا أَزِيدُكَ عَلَيْهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ قَوْمًا يَخْرُجُونَ مِنْ هَاهُنَا وَأَشَارَ بِيَدِهِ نَحْوَ ‏ ‏الْعِرَاقِ ‏ ‏يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏حَنَاجِرَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏قُلْتُ هَلْ ذَكَرَ لَهُمْ عَلَامَةً ‏ ‏قَالَ ‏ ‏هَذَا مَا سَمِعْتُ لَا أَزِيدُكَ عَلَيْهِ ‏","","",""],[15411,15411,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ يَعْنِي ابْنَ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏جَدَّتِي ‏ ‏الرَّبَابُ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَتْ سَمِعْتُ ‏ ‏سَهْلَ بْنَ حُنَيْفٍ ‏ ‏يَقُولُ ‏ ‏مَرَرْنَا بِسَيْلٍ فَدَخَلْتُ فَاغْتَسَلْتُ مِنْهُ فَخَرَجْتُ ‏ ‏مَحْمُومًا ‏ ‏فَنُمِيَ ‏ ‏ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مُرُوا ‏ ‏أَبَا ثَابِتٍ ‏ ‏يَتَعَوَّذُ قُلْتُ يَا سَيِّدِي ‏ ‏وَالرُّقَى ‏ ‏صَالِحَةٌ قَالَ ‏ ‏لَا ‏ ‏رُقْيَةَ ‏ ‏إِلَّا فِي نَفْسٍ أَوْ ‏ ‏حُمَةٍ ‏ ‏أَوْ لَدْغَةٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏النَّظْرَةُ وَاللَّدْغَةُ ‏ ‏وَالْحُمَةُ ‏","","",""],[15412,15412,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏أَبِي طَلْحَةَ الْأَنْصَارِيِّ ‏ ‏يَعُودُهُ ‏ ‏قَالَ فَوَجَدْنَا عِنْدَهُ ‏ ‏سَهْلَ بْنَ حُنَيْفٍ ‏ ‏قَالَ فَدَعَا ‏ ‏أَبُو طَلْحَةَ ‏ ‏إِنْسَانًا فَنَزَعَ ‏ ‏نَمَطًا ‏ ‏تَحْتَهُ فَقَالَ لَهُ ‏ ‏سَهْلُ بْنُ حُنَيْفٍ ‏ ‏لِمَ تَنْتَزِعُهُ قَالَ لِأَنَّ فِيهِ تَصَاوِيرَ وَقَدْ قَالَ فِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قَدْ عَلِمْتَ قَالَ ‏ ‏سَهْلٌ ‏ ‏أَوَلَمْ يَقُلْ ‏ ‏إِلَّا مَا كَانَ ‏ ‏رَقْمًا ‏ ‏فِي ثَوْبٍ قَالَ بَلَى وَلَكِنَّهُ أَطْيَبُ لِنَفْسِي ‏","","",""],[15413,15413,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ وَسَارُوا مَعَهُ نَحْوَ ‏ ‏مَكَّةَ ‏ ‏حَتَّى إِذَا كَانُوا ‏ ‏بِشِعْبِ ‏ ‏الْخَزَّارِ ‏ ‏مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏اغْتَسَلَ ‏ ‏سَهْلُ بْنُ حُنَيْفٍ ‏ ‏وَكَانَ رَجُلًا أَبْيَضَ حَسَنَ الْجِسْمِ وَالْجِلْدِ فَنَظَرَ إِلَيْهِ ‏ ‏عَامِرُ بْنُ رَبِيعَةَ ‏ ‏أَخُو ‏ ‏بَنِي عَدِيِّ بْنِ كَعْبٍ ‏ ‏وَهُوَ يَغْتَسِلُ فَقَالَ مَا رَأَيْتُ كَالْيَوْمِ وَلَا جِلْدَ مُخَبَّأَةٍ ‏ ‏فَلُبِطَ ‏ ‏سَهْلٌ ‏ ‏فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ لَهُ يَا رَسُولَ اللَّهِ هَلْ لَكَ فِي ‏ ‏سَهْلٍ ‏ ‏وَاللَّهِ مَا يَرْفَعُ رَأْسَهُ وَمَا يُفِيقُ قَالَ هَلْ تَتَّهِمُونَ فِيهِ مِنْ أَحَدٍ قَالُوا نَظَرَ إِلَيْهِ ‏ ‏عَامِرُ بْنُ رَبِيعَةَ ‏ ‏فَدَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامِرًا ‏ ‏فَتَغَيَّظَ عَلَيْهِ وَقَالَ عَلَامَ يَقْتُلُ أَحَدُكُمْ أَخَاهُ هَلَّا إِذَا رَأَيْتَ مَا يُعْجِبُكَ بَرَّكْتَ ثُمَّ قَالَ لَهُ ‏ ‏اغْتَسِلْ لَهُ فَغَسَلَ وَجْهَهُ وَيَدَيْهِ وَمِرْفَقَيْهِ وَرُكْبَتَيْهِ ‏ ‏وَأَطْرَافَ رِجْلَيْهِ وَدَاخِلَةَ إِزَارِهِ فِي ‏ ‏قَدَحٍ ‏ ‏ثُمَّ صُبَّ ذَلِكَ الْمَاءُ عَلَيْهِ يَصُبُّهُ رَجُلٌ عَلَى رَأْسِهِ وَظَهْرِهِ مِنْ خَلْفِهِ يُكْفِئُ ‏ ‏الْقَدَحَ ‏ ‏وَرَاءَهُ فَفَعَلَ بِهِ ذَلِكَ فَرَاحَ ‏ ‏سَهْلٌ ‏ ‏مَعَ النَّاسِ لَيْسَ بِهِ بَأْسٌ ‏","","",""],[15414,15414,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏مُجَمِّعُ بْنُ يَعْقُوبَ الْأَنْصَارِيُّ ‏ ‏بِقُبَاءٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْكَرْمَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ بْنَ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏يَقُولُ قَالَ ‏ ‏أَبِي ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ خَرَجَ حَتَّى يَأْتِيَ هَذَا الْمَسْجِدَ ‏ ‏يَعْنِي مَسْجِدَ ‏ ‏قُبَاءٍ ‏ ‏فَيُصَلِّيَ فِيهِ كَانَ كَعَدْلِ عُمْرَةٍ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُجَمِّعُ بْنُ يَعْقُوبَ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سُلَيْمَانَ الْكَرْمَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ بْنَ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏فَذَكَرَ مِثْلَهُ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَاتِمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُلَيْمَانَ الْكَرْمَانِيُّ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[15415,15415,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْكَرِيمِ بْنُ أَبِي الْمُخَارِقِ ‏ ‏أَنَّ ‏ ‏الْوَلِيدَ بْنَ مَالِكِ بْنِ عَبْدِ الْقَيْسِ ‏ ‏أَخْبَرَهُ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏مِنْ ‏ ‏عَبْدِ الْقَيْسِ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ قَيْسٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏سَهْلًا ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ قَالَ أَنْتَ رَسُولِي إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏قُلْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْسَلَنِي يَقْرَأُ عَلَيْكُمْ السَّلَامَ ‏ ‏وَيَأْمُرُكُمْ بِثَلَاثٍ لَا تَحْلِفُوا بِغَيْرِ اللَّهِ وَإِذَا تَخَلَّيْتُمْ فَلَا تَسْتَقْبِلُوا الْقِبْلَةَ وَلَا ‏ ‏تَسْتَدْبِرُوهَا ‏ ‏وَلَا ‏ ‏تَسْتَنْجُوا ‏ ‏بِعَظْمٍ وَلَا ‏ ‏بِبَعْرَةٍ ‏","","",""],[15416,15416,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أُذِلَّ عِنْدَهُ مُؤْمِنٌ فَلَمْ يَنْصُرْهُ وَهُوَ قَادِرٌ عَلَى أَنْ يَنْصُرَهُ أَذَلَّهُ اللَّهُ عَزَّ وَجَلَّ عَلَى رُءُوسِ الْخَلَائِقِ يَوْمَ الْقِيَامَةِ ‏","","",""],[15417,15417,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَعَانَ مُجَاهِدًا فِي سَبِيلِ اللَّهِ أَوْ ‏ ‏غَارِمًا ‏ ‏فِي عُسْرَتِهِ أَوْ ‏ ‏مُكَاتَبًا ‏ ‏فِي رَقَبَتِهِ أَظَلَّهُ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ ‏","","",""],[15418,15418,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏أَنَّ ‏ ‏سَهْلًا ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعَانَ مُجَاهِدًا فِي سَبِيلِ اللَّهِ أَوْ ‏ ‏غَارِمًا ‏ ‏فِي عُسْرَتِهِ أَوْ ‏ ‏مُكَاتَبًا ‏ ‏فِي رَقَبَتِهِ أَظَلَّهُ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ ‏","","",""],[15419,15419,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي حَرْبٍ ‏ ‏أَنَّ ‏ ‏طَلْحَةَ ‏ ‏حَدَّثَهُ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏الْمَدِينَةَ ‏ ‏وَلَيْسَ لِي بِهَا مَعْرِفَةٌ فَنَزَلْتُ فِي ‏ ‏الصُّفَّةِ ‏ ‏مَعَ رَجُلٍ فَكَانَ بَيْنِي وَبَيْنَهُ كُلَّ يَوْمٍ ‏ ‏مُدٌّ ‏ ‏مِنْ تَمْرٍ فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فَلَمَّا انْصَرَفَ قَالَ رَجُلٌ مِنْ ‏ ‏أَصْحَابِ الصُّفَّةِ ‏ ‏يَا رَسُولَ اللَّهِ أَحْرَقَ بُطُونَنَا التَّمْرُ وَتَخَرَّقَتْ عَنَّا ‏ ‏الْخُنُفُ ‏ ‏فَصَعِدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَطَبَ ثُمَّ قَالَ وَاللَّهِ ‏ ‏لَوْ وَجَدْتُ خُبْزًا أَوْ لَحْمًا لَأَطْعَمْتُكُمُوهُ أَمَا إِنَّكُمْ تُوشِكُونَ أَنْ تُدْرِكُوا وَمَنْ أَدْرَكَ ذَلِكَ مِنْكُمْ أَنْ يُرَاحَ عَلَيْكُمْ ‏ ‏بِالْجِفَانِ ‏ ‏وَتَلْبَسُونَ مِثْلَ أَسْتَارِ ‏ ‏الْكَعْبَةِ ‏ ‏قَالَ فَمَكَثْتُ أَنَا وَصَاحِبِي ثَمَانِيَةَ عَشَرَ يَوْمًا وَلَيْلَةً مَا لَنَا طَعَامٌ إِلَّا ‏ ‏الْبَرِيرَ ‏ ‏حَتَّى جِئْنَا إِلَى إِخْوَانِنَا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَوَاسَوْنَا وَكَانَ خَيْرَ مَا أَصَبْنَا هَذَا التَّمْرُ ‏","","",""],[15420,15420,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ الرَّازِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ الْفَضْلِ الْأَنْصَارِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعْدُ بْنُ طَارِقٍ الْأَشْجَعِيُّ وَهُوَ أَبُو مَالِكٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ نُعَيْمِ بْنِ مَسْعُودٍ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏نُعَيْمٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ حِينَ قَرَأَ كِتَابَ ‏ ‏مُسَيْلِمَةَ الْكَذَّابِ ‏ ‏قَالَ لِلرَّسُولَيْنِ فَمَا تَقُولَانِ أَنْتُمَا قَالَا نَقُولُ كَمَا قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ ‏ ‏لَوْلَا أَنَّ الرُّسُلَ لَا تُقْتَلُ لَضَرَبْتُ أَعْنَاقَكُمَا ‏","","",""],[15421,15421,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ الْأَنْصَارِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُشَيْرُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ النُّعْمَانِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ ‏ ‏بِالصَّهْبَاءِ ‏ ‏عَامَ ‏ ‏خَيْبَرَ ‏ ‏فَلَمَّا صَلَّى الْعَصْرَ ‏ ‏دَعَا بِالْأَطْعِمَةِ فَلَمْ يُؤْتَ إِلَّا ‏ ‏بِسَوِيقٍ ‏ ‏قَالَ فَلُكْنَا ‏ ‏يَعْنِي أَكَلْنَا ‏ ‏مِنْهُ فَلَمَّا كَانَتْ الْمَغْرِبُ تَمَضْمَضَ وَتَمَضْمَضْنَا مَعَهُ ‏","","",""],[15422,15422,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الْأَقْرَعِ بْنِ حَابِسٍ ‏ ‏أَنَّهُ نَادَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ وَرَاءِ ‏ ‏الْحُجُرَاتِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ فَلَمْ يُجِبْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَلَا إِنَّ حَمْدِي زَيْنٌ وَإِنَّ ذَمِّي ‏ ‏شَيْنٌ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا حَدَّثَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏ذَاكَ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[15423,15423,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْمُرَقِّعُ بْنُ صَيْفِيٍّ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رَبَاحِ بْنِ الرَّبِيعِ ‏ ‏أَخِي ‏ ‏حَنْظَلَةَ الْكَاتِبِ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ خَرَجَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ غَزَاهَا وَعَلَى مُقَدِّمَتِهِ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏فَمَرَّ ‏ ‏رَبَاحٌ ‏ ‏وَأَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى امْرَأَةٍ مَقْتُولَةٍ مِمَّا أَصَابَتْ الْمُقَدِّمَةُ فَوَقَفُوا يَنْظُرُونَ إِلَيْهَا وَيَتَعَجَّبُونَ مِنْ خَلْقِهَا حَتَّى لَحِقَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى رَاحِلَتِهِ فَانْفَرَجُوا عَنْهَا فَوَقَفَ عَلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا كَانَتْ هَذِهِ لِتُقَاتِلَ فَقَالَ لِأَحَدِهِمْ الْحَقْ ‏ ‏خَالِدًا ‏ ‏فَقُلْ لَهُ ‏ ‏لَا تَقْتُلُونَ ‏ ‏ذُرِّيَّةً ‏ ‏وَلَا ‏ ‏عَسِيفًا ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْمُرَقِّعُ بْنُ صَيْفِيِّ بْنِ رَبَاحٍ ‏ ‏أَنَّ ‏ ‏رَبَاحًا ‏ ‏جَدَّهُ ‏ ‏ابْنَ الرَّبِيعِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْمُرَقِّعِ بْنِ صَيْفِيِّ بْنِ رَبَاحٍ ‏ ‏أَخِي ‏ ‏حَنْظَلَةَ الْكَاتِبِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَدِّي ‏ ‏أَنَّهُ خَرَجَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏أُخْبِرْتُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُرَقِّعُ بْنُ صَيْفِيٍّ التَّمِيمِيُّ ‏ ‏شَهِدَ عَلَى ‏ ‏جَدِّهِ ‏ ‏رَبَاحِ بْنِ رَبِيعٍ الْحَنْظَلِيِّ الْكَاتِبِ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ خَرَجَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏ابْنِ أَبِي الزِّنَادِ ‏","","",""],[15424,15424,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوَيْهِبَةَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمِرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُصَلِّيَ عَلَى أَهْلِ ‏ ‏الْبَقِيعِ ‏ ‏فَصَلَّى عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً ثَلَاثَ مَرَّاتٍ فَلَمَّا كَانَتْ لَيْلَةُ الثَّانِيَةِ قَالَ يَا ‏ ‏أَبَا مُوَيْهِبَةَ ‏ ‏أَسْرِجْ ‏ ‏لِي دَابَّتِي قَالَ فَرَكِبَ فَمَشَيْتُ حَتَّى انْتَهَى إِلَيْهِمْ فَنَزَلَ عَنْ دَابَّتِهِ وَأَمْسَكَتْ الدَّابَّةُ وَوَقَفَ عَلَيْهِمْ ‏ ‏أَوْ قَالَ قَامَ عَلَيْهِمْ ‏ ‏فَقَالَ ‏ ‏لِيَهْنِيكُمْ مَا أَنْتُمْ فِيهِ مِمَّا فِيهِ النَّاسُ أَتَتْ الْفِتَنُ كَقِطَعِ اللَّيْلِ يَرْكَبُ بَعْضُهَا بَعْضًا الْآخِرَةُ أَشَدُّ مِنْ الْأُولَى ‏ ‏فَلْيَهْنِيكُمْ مَا أَنْتُمْ فِيهِ ثُمَّ رَجَعَ فَقَالَ يَا ‏ ‏أَبَا مُوَيْهِبَةَ ‏ ‏إِنِّي ‏ ‏أُعْطِيتُ ‏ ‏أَوْ قَالَ خُيِّرْتُ ‏ ‏مَفَاتِيحَ مَا يُفْتَحُ عَلَى أُمَّتِي مِنْ ‏ ‏بَعْدِي وَالْجَنَّةَ أَوْ لِقَاءَ رَبِّي فَقُلْتُ بِأَبِي وَأُمِّي يَا رَسُولَ اللَّهِ فَأَخْبِرْنِي قَالَ لَأَنْ تُرَدَّ عَلَى عَقِبِهَا مَا شَاءَ اللَّهُ فَاخْتَرْتُ لِقَاءَ رَبِّي عَزَّ وَجَلَّ فَمَا لَبِثَ بَعْدَ ذَلِكَ إِلَّا سَبْعًا ‏ ‏أَوْ ثَمَانِيًا ‏ ‏حَتَّى قُبِضَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏مَرَّةً تُرَدُّ عَلَى عَقِبَيْهَا ‏","","",""],[15425,15425,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ الْعَبْلِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُبَيْدُ بْنُ جُبَيْرٍ ‏ ‏مَوْلَى ‏ ‏الْحَكَمِ بْنِ أَبِي الْعَاصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي مُوَيْهِبَةَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ جَوْفِ اللَّيْلِ فَقَالَ يَا ‏ ‏أَبَا مُوَيْهِبَةَ ‏ ‏إِنِّي قَدْ أُمِرْتُ أَنْ أَسْتَغْفِرَ لِأَهْلِ ‏ ‏الْبَقِيعِ ‏ ‏فَانْطَلِقْ مَعِي فَانْطَلَقْتُ مَعَهُ فَلَمَّا وَقَفَ بَيْنَ أَظْهُرِهِمْ قَالَ السَّلَامُ عَلَيْكُمْ يَا أَهْلَ الْمَقَابِرِ ‏ ‏لِيَهْنِ لَكُمْ مَا أَصْبَحْتُمْ فِيهِ مِمَّا أَصْبَحَ فِيهِ النَّاسُ لَوْ تَعْلَمُونَ مَا نَجَّاكُمْ اللَّهُ مِنْهُ أَقْبَلَتْ ‏ ‏الْفِتَنُ ‏ ‏كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يَتْبَعُ أَوَّلُهَا آخِرَهَا الْآخِرَةُ شَرٌّ مِنْ الْأُولَى قَالَ ثُمَّ أَقْبَلَ عَلَيَّ فَقَالَ يَا ‏ ‏أَبَا مُوَيْهِبَةَ ‏ ‏إِنِّي قَدْ أُوتِيتُ مَفَاتِيحَ خَزَائِنِ الدُّنْيَا وَالْخُلْدَ فِيهَا ثُمَّ الْجَنَّةَ وَخُيِّرْتُ بَيْنَ ذَلِكَ وَبَيْنَ لِقَاءِ رَبِّي عَزَّ وَجَلَّ وَالْجَنَّةِ قَالَ قُلْتُ بِأَبِي وَأُمِّي فَخُذْ مَفَاتِيحَ الدُّنْيَا وَالْخُلْدَ فِيهَا ثُمَّ الْجَنَّةَ قَالَ لَا وَاللَّهِ يَا ‏ ‏أَبَا مُوَيْهِبَةَ ‏ ‏لَقَدْ اخْتَرْتُ لِقَاءَ رَبِّي عَزَّ وَجَلَّ وَالْجَنَّةَ ثُمَّ اسْتَغْفَرَ لِأَهْلِ ‏ ‏الْبَقِيعِ ‏ ‏ثُمَّ انْصَرَفَ فَبُدِئَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَجَعِهِ الَّذِي قَضَاهُ اللَّهُ عَزَّ وَجَلَّ فِيهِ حِينَ أَصْبَحَ ‏","","",""],[15426,15426,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ حُبَيْشٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى ‏ ‏عُبَادَةَ بْنِ الصَّامِتِ ‏ ‏يَعُودُهُ ‏ ‏فِي مَرَضِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَعْلَمُونَ مَنْ الشَّهِيدُ مِنْ أُمَّتِي ‏ ‏فَأَرَمَّ ‏ ‏الْقَوْمُ فَقَالَ ‏ ‏عُبَادَةُ ‏ ‏سَانِدُونِي فَأَسْنَدُوهُ فَقَالَ يَا رَسُولَ اللَّهِ الصَّابِرُ الْمُحْتَسِبُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ شُهَدَاءَ أُمَّتِي إِذًا لَقَلِيلٌ الْقَتْلُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ شَهَادَةٌ وَالطَّاعُونُ شَهَادَةٌ ‏ ‏وَالْغَرَقُ ‏ ‏شَهَادَةٌ ‏ ‏وَالْبَطْنُ ‏ ‏شَهَادَةٌ وَالنُّفَسَاءُ يَجُرُّهَا وَلَدُهَا بِسُرَرِهِ إِلَى الْجَنَّةِ ‏ ‏قَالَ ‏ ‏وَزَادَ فِيهَا ‏ ‏أَبُو الْعَوَّامِ ‏ ‏سَادِنُ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏وَالْحَرْقُ وَالسَّيْلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏صَاحِبٍ لَهُ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ الصَّامِتِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاهُ ‏ ‏يَعُودُهُ ‏ ‏فِي مَرَضِهِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[15427,15427,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏أَبِي حَبَّةَ الْبَدْرِيِّ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ ‏لَمْ يَكُنْ ‏ ‏قَالَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنَّ رَبَّكَ يَأْمُرُكَ أَنْ تُقْرِئَ هَذِهِ السُّورَةَ ‏ ‏أُبَيَّ بْنَ كَعْبٍ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أُبَيُّ ‏ ‏إِنَّ رَبِّي عَزَّ وَجَلَّ أَمَرَنِي أَنْ أُقْرِئَكَ هَذِهِ السُّورَةَ فَبَكَى وَقَالَ ذُكِرْتُ ‏ ‏ثَمَّةَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[15428,15428,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَبَّةَ الْبَدْرِيَّ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ ‏لَمْ يَكُنْ الَّذِينَ كَفَرُوا مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏إِلَى آخِرِهَا قَالَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ رَبَّكَ يَأْمُرُكَ أَنْ تُقْرِئَهَا ‏ ‏أُبَيًّا ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأُبَيٍّ ‏ ‏إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَمَرَنِي أَنْ أُقْرِئَكَ هَذِهِ السُّورَةَ قَالَ ‏ ‏أُبَيٌّ ‏ ‏وَقَدْ ذُكِرْتُ ثَمَّ يَا رَسُولَ اللَّهِ قَالَ نَعَمْ قَالَ فَبَكَى ‏ ‏أُبَيٌّ ‏","","",""],[15429,15429,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏مَعْرُوفٌ يَعْنِي ابْنَ وَاصِلٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏حَفْصَةُ ابْنَةُ طَلْقٍ ‏ ‏امْرَأَةٌ مِنْ الْحَيِّ سَنَةَ تِسْعِينَ ‏ ‏عَنْ ‏ ‏أَبِي عُمَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا فَجَاءَ رَجُلٌ بِطَبَقٍ عَلَيْهِ ‏ ‏تَمْرٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا هَذَا ‏ ‏أَصَدَقَةٌ ‏ ‏أَمْ هَدِيَّةٌ قَالَ ‏ ‏صَدَقَةٌ ‏ ‏قَالَ فَقَدِّمْهُ إِلَى الْقَوْمِ ‏ ‏وَحَسَنٌ ‏ ‏صَلَوَاتُ اللَّهِ وَسَلَامُهُ عَلَيْهِ يَتَعَفَّرُ بَيْنَ يَدَيْهِ فَأَخَذَ الصَّبِيُّ تَمْرَةً فَجَعَلَهَا فِي ‏ ‏فِيهِ فَأَدْخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُصْبُعَهُ فِي ‏ ‏فِي الصَّبِيِّ فَنَزَعَ التَّمْرَةَ فَقَذَفَ بِهَا ثُمَّ قَالَ ‏ ‏إِنَّا آلَ ‏ ‏مُحَمَّدٍ ‏ ‏لَا تَحِلُّ لَنَا ‏ ‏الصَّدَقَةُ ‏ ‏فَقُلْتُ ‏ ‏لِمَعْرُوفٍ ‏ ‏أَبُو عُمَيْرٍ ‏ ‏جَدُّكَ ‏ ‏قَالَ ‏ ‏جَدُّ أَبِي قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْرُوفٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِي عَمِيرَةَ أُسَيْدِ بْنِ مَالِكٍ ‏ ‏جَدِّ ‏ ‏مَعْرُوفٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[15430,15430,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ الْخَوْلَانِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُمَرُ بْنُ رُؤْبَةَ التَّغْلِبِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْوَاحِدِ بْنِ عَبْدِ اللَّهِ النَّصْرِيِّ ‏ ‏عَنْ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ اللَّيْثِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْأَةُ تَحُوزُ ثَلَاثَ مَوَارِيثَ عَتِيقَهَا ‏ ‏وَلَقِيطَهَا ‏ ‏وَوَلَدَهَا الَّذِي ‏ ‏لَاعَنَتْ ‏ ‏عَلَيْهِ ‏","","",""],[15431,15431,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمُ بْنُ خَارِجَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو عَبْدِ الْمَلِكِ الْحَسَنُ بْنُ يَحْيَى الْخُشَنِيُّ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ حَيَّانَ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏وَاثِلَةُ بْنُ الْأَسْقَعِ ‏ ‏وَنَحْنُ نَبْنِي مَسْجِدَنَا قَالَ فَوَقَفَ عَلَيْنَا فَسَلَّمَ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ بَنَى مَسْجِدًا يُصَلَّى فِيهِ بَنَى اللَّهُ عَزَّ وَجَلَّ لَهُ فِي الْجَنَّةِ أَفْضَلَ مِنْهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَقَدْ ‏ ‏سَمِعْتُهُ ‏ ‏مِنْ ‏ ‏هَيْثَمِ بْنِ خَارِجَةَ ‏","","",""],[15432,15432,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ يَعْنِي ابْنَ أَبِي حَبِيبٍ ‏ ‏أَنَّ ‏ ‏رَبِيعَةَ بْنَ يَزِيدَ الدِّمَشْقِيَّ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏وَاثِلَةَ يَعْنِي ابْنَ الْأَسْقَعِ ‏ ‏قَالَ ‏ ‏كُنْتُ مِنْ ‏ ‏أَهْلِ الصُّفَّةِ ‏ ‏فَدَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا بِقُرْصٍ فَكَسَرَهُ فِي ‏ ‏الْقَصْعَةِ ‏ ‏وَصَنَعَ فِيهَا مَاءً سُخْنًا ثُمَّ صَنَعَ فِيهَا وَدَكًا ثُمَّ ‏ ‏سَفْسَفَهَا ‏ ‏ثُمَّ ‏ ‏لَبَّقَهَا ‏ ‏ثُمَّ ‏ ‏صَعْنَبَهَا ‏ ‏ثُمَّ قَالَ اذْهَبْ فَأْتِنِي بِعَشَرَةٍ أَنْتَ عَاشِرُهُمْ فَجِئْتُ بِهِمْ فَقَالَ ‏ ‏كُلُوا وَكُلُوا مِنْ أَسْفَلِهَا وَلَا تَأْكُلُوا مِنْ أَعْلَاهَا فَإِنَّ الْبَرَكَةَ تَنْزِلُ مِنْ أَعْلَاهَا فَأَكَلُوا مِنْهَا حَتَّى شَبِعُوا ‏","","",""],[15433,15433,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَلِيحِ بْنِ أُسَامَةَ ‏ ‏عَنْ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ بِالسِّوَاكِ حَتَّى خَشِيتُ أَنْ يُكْتَبَ عَلَيَّ ‏","","",""],[15434,15434,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ يَزِيدَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏وَاثِلَةَ بْنَ الْأَسْقَعِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَعْظَمَ ‏ ‏الْفِرَى ‏ ‏ثَلَاثَةٌ أَنْ يَفْتَرِيَ الرَّجُلُ عَلَى عَيْنَيْهِ يَقُولُ رَأَيْتُ وَلَمْ يَرَ وَأَنْ يَفْتَرِيَ عَلَى وَالِدَيْهِ ‏ ‏فَيُدْعَى إِلَى غَيْرِ أَبِيهِ أَوْ يَقُولُ سَمِعَنِي وَلَمْ يَسْمَعْ مِنِّي ‏","","",""],[15435,15435,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو فَضَالَةَ الْفَرَجُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَعْدٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏وَاثِلَةَ بْنَ الْأَسْقَعِ ‏ ‏يُصَلِّي فِي مَسْجِدِ ‏ ‏دِمَشْقَ ‏ ‏فَبَزَقَ تَحْتَ رِجْلِهِ الْيُسْرَى ثُمَّ عَرَكَهَا بِرِجْلِهِ فَلَمَّا انْصَرَفَ قُلْتُ أَنْتَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَبْزُقُ فِي الْمَسْجِدِ قَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ ‏","","",""],[15436,15436,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ هَاشِمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ عُلَاثَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي عَبْلَةَ ‏ ‏عَنْ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏قَالَ ‏ ‏جَاءَ نَفَرٌ مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ صَاحِبًا لَنَا قَدْ ‏ ‏أَوْجَبَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَعْتِقْ رَقَبَةً ‏ ‏مُسْلِمَةً ‏ ‏يَفُكَّ اللَّهُ عَزَّ وَجَلَّ بِكُلِّ عُضْوٍ مِنْهَا عُضْوًا مِنْهُ مِنْ النَّارِ ‏","","",""],[15437,15437,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ الْحِمْصِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ الْحِمْصِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ رُؤْبَةَ التَّغْلِبِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ عَبْدِ اللَّهِ النَّصْرِيُّ ‏ ‏عَنْ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْأَةُ تَحُوزُ ثَلَاثَ مَوَارِيثَ عَتِيقَهَا ‏ ‏وَلَقِيطَهَا ‏ ‏وَوَلَدَهَا الَّذِي ‏ ‏تُلَاعِنُ ‏ ‏عَلَيْهِ ‏","","",""],[15438,15438,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ضَمْرَةُ بْنُ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ أَبِي عَبْلَةَ ‏ ‏عَنِ ‏ ‏الْغَرِيفِ الدَّيْلَمِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏وَاثِلَةَ بْنَ الْأَسْقَعِ اللَّيْثِيَّ ‏ ‏فَقُلْنَا حَدِّثْنَا بِحَدِيثٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَتَيْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَاحِبٍ لَنَا قَدْ ‏ ‏أَوْجَبَ ‏ ‏فَقَالَ ‏ ‏أَعْتِقُوا عَنْهُ يُعْتِقْ اللَّهُ عَزَّ وَجَلَّ بِكُلِّ عُضْوٍ عُضْوًا مِنْهُ مِنْ النَّارِ ‏","","",""],[15439,15439,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ يَعْنِي الرَّازِيَّ ‏ ‏عَنْ ‏ ‏يَزِيْدَ بْنِ أَبِي مَالِكٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سِبَاعٍ ‏ ‏قَالَ ‏ ‏اشْتَرَيْتُ نَاقَةً مِنْ دَارِ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏فَلَمَّا خَرَجْتُ بِهَا أَدْرَكَنَا ‏ ‏وَاثِلَةُ ‏ ‏وَهُوَ يَجُرُّ رِدَاءَهُ فَقَالَ يَا عَبَد اللَّهِ اشْتَرَيْتَ قُلْتُ نَعَمْ قَالَ هَلْ بَيَّنَ لَكَ مَا فِيهَا قُلْتُ وَمَا فِيهَا قَالَ إِنَّهَا لَسَمِينَةٌ ظَاهِرَةُ الصِّحَّةِ قَالَ فَقَالَ أَرَدْتَ بِهَا سَفَرًا أَمْ أَرَدْتَ بِهَا لَحْمًا قُلْتُ بَلْ أَرَدْتُ عَلَيْهَا الْحَجَّ قَالَ فَإِنَّ ‏ ‏بِخُفِّهَا ‏ ‏نَقْبًا ‏ ‏قَالَ فَقَالَ صَاحِبُهَا أَصْلَحَكَ اللَّهُ أَيْ هَذَا تُفْسِدُ عَلَيَّ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحِلُّ لِأَحَدٍ يَبِيعُ شَيْئًا إِلَّا يُبَيِّنُ مَا فِيهِ وَلَا يَحِلُّ لِمَنْ يَعْلَمُ ذَلِكَ إِلَّا يُبَيِّنُهُ ‏","","",""],[15440,15440,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَبِي مَلِيحِ بْنِ أُسَامَةَ ‏ ‏عَنْ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ وَأَتَاهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ ‏ ‏حَدًّا ‏ ‏مِنْ ‏ ‏حُدُودِ ‏ ‏اللَّهِ عَزَّ وَجَلَّ فَأَقِمْ فِيَّ ‏ ‏حَدَّ ‏ ‏اللَّهِ فَأَعْرَضَ ثُمَّ أَتَاهُ الثَّانِيَةَ فَأَعْرَضَ عَنْهُ ثُمَّ قَالَهَا الثَّالِثَةَ فَأَعْرَضَ عَنْهُ ثُمَّ أُقِيمَتْ الصَّلَاةُ فَلَمَّا قَضَى الصَّلَاةَ أَتَاهُ الرَّابِعَةَ فَقَالَ إِنِّي أَصَبْتُ ‏ ‏حَدًّا ‏ ‏مِنْ ‏ ‏حُدُودِ ‏ ‏اللَّهِ عَزَّ وَجَلَّ فَأَقِمْ فِيَّ ‏ ‏حَدَّ ‏ ‏اللَّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏فَدَعَاهُ فَقَالَ أَلَمْ تُحْسِنْ الطُّهُورَ ‏ ‏أَوْ الْوُضُوءَ ‏ ‏ثُمَّ شَهِدْتَ الصَّلَاةَ مَعَنَا ‏ ‏آنِفًا ‏ ‏قَالَ بَلَى قَالَ اذْهَبْ فَهِيَ كَفَّارَتُكَ ‏","","",""],[15441,15441,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَبِيعَةُ بْنُ يَزِيدَ الدِّمَشْقِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏وَاثِلَةَ بْنَ الْأَسْقَعِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَعْظَمَ ‏ ‏الْفِرْيَةِ ‏ ‏ثَلَاثٌ أَنْ يَفْتَرِيَ الرَّجُلُ عَلَى عَيْنَيْهِ يَقُولُ رَأَيْتُ وَلَمْ يَرَ وَأَنْ يَفْتَرِيَ عَلَى وَالِدَيْهِ يُدْعَى إِلَى غَيْرِ أَبِيهِ وَأَنْ يَقُولَ قَدْ سَمِعْتُ وَلَمْ يَسْمَعْ ‏","","",""],[15442,15442,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنِ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْوَلِيدُ بْنُ سُلَيْمَانَ يَعْنِي ابْنَ أَبِي السَّائِبِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَيَّانُ أَبُو النَّضْرِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏عَلَى ‏ ‏أَبِي الْأَسْوَدِ الْجُرَشِيِّ ‏ ‏فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ فَسَلَّمَ عَلَيْهِ وَجَلَسَ قَالَ فَأَخَذَ ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏يَمِينَ ‏ ‏وَاثِلَةَ ‏ ‏فَمَسَحَ بِهَا عَلَى عَيْنَيْهِ وَوَجْهِهِ لِبَيْعَتِهِ بِهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ ‏ ‏وَاثِلَةُ ‏ ‏وَاحِدَةٌ أَسْأَلُكَ عَنْهَا قَالَ وَمَا هِيَ قَالَ كَيْفَ ظَنُّكَ بِرَبِّكَ قَالَ فَقَالَ ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏وَأَشَارَ بِرَأْسِهِ أَيْ حَسَنٌ قَالَ ‏ ‏وَاثِلَةُ ‏ ‏أَبْشِرْ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي فَلْيَظُنَّ بِي مَا شَاءَ قَالَ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏وَهِشَامُ بْنُ الْغَازِ ‏ ‏أَنَّهُمَا سَمِعَاهُ ‏ ‏مِنْ ‏ ‏حَيَّانَ أَبِي النَّضْرِ ‏ ‏يُحَدِّثُ ‏ ‏بِهِ ‏ ‏وَلَا يَأْتِيَانِ عَلَى حِفْظِ ‏ ‏الْوَلِيدِ بْنِ سُلَيْمَانَ ‏","","",""],[15443,15443,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ جَنَاحٍ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ مَيْسَرَةَ بْنِ حَلْبَسٍ ‏ ‏عَنْ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَلَا إِنَّ فُلَانَ بْنَ فُلَانٍ فِي ‏ ‏ذِمَّتِكَ ‏ ‏وَحَبْلِ جِوَارِكَ فَقِهِ ‏ ‏فِتْنَةَ ‏ ‏الْقَبْرِ وَعَذَابَ النَّارِ أَنْتَ أَهْلُ الْوَفَاءِ وَالْحَقِّ اللَّهُمَّ فَاغْفِرْ لَهُ وَارْحَمْهُ فَإِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ ‏","","",""],[15444,15444,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي شَيْبَةَ يَحْيَى بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْوَهَّابِ الْمَكِّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْوَاحِدِ بْنِ عَبْدِ اللَّهِ النَّصْرِيِّ ‏ ‏عَنْ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمُسْلِمُ عَلَى الْمُسْلِمِ حَرَامٌ دَمُهُ وَعِرْضُهُ وَمَالُهُ الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَخْذُلُهُ وَالتَّقْوَى هَاهُنَا وَأَوْمَأَ بِيَدِهِ إِلَى الْقَلْبِ قَالَ وَحَسْبُ امْرِئٍ مِنْ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ ‏","","",""],[15445,15445,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ عَبْدِ اللَّهِ الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدِ بْنِ أَبِي عُبَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ خَالِدٍ الْقَارِظِيِّ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ عَبَّادٍ الدِّيلِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا لَهَبٍ ‏ ‏بِعُكَاظٍ ‏ ‏وَهُوَ يَتْبَعُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ يَا أَيُّهَا النَّاسُ إِنَّ هَذَا قَدْ غَوَى فَلَا يُغْوِيَنَّكُمْ عَنْ آلِهَةِ آبَائِكُمْ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفِرُّ مِنْهُ وَهُوَ عَلَى أَثَرِهِ وَنَحْنُ نَتْبَعُهُ وَنَحْنُ غِلْمَانُ كَأَنِّي أَنْظُرُ إِلَيْهِ أَحْوَلَ ذَا ‏ ‏غَدِيرَتَيْنِ ‏ ‏أَبْيَضَ النَّاسِ وَأَجْمَلَهُمْ ‏","","",""],[15446,15446,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ بُنْدَارٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ عَبَّادٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذِي الْمَجَازِ ‏ ‏يَدْعُو النَّاسَ وَخَلْفَهُ رَجُلٌ أَحْوَلُ يَقُولُ لَا يَصُدَّنَّكُمْ هَذَا عَنْ دِينِ آلِهَتِكُمْ قُلْتُ مَنْ هَذَا قَالُوا هَذَا عَمُّهُ ‏ ‏أَبُو لَهَبٍ ‏","","",""],[15447,15447,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏سُرَيْجُ بْنُ يُونُسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ عَبَّادٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَدْعُو النَّاسَ إِلَى الْإِسْلَامِ ‏ ‏بِذِي الْمَجَازِ ‏ ‏وَخَلْفَهُ رَجُلٌ أَحْوَلُ يَقُولُ لَا يَغْلِبَنَّكُمْ هَذَا عَنْ دِينِكُمْ وَدِينِ آبَائِكُمْ قُلْتُ لِأَبِي وَأَنَا غُلَامٌ مَنْ هَذَا الْأَحْوَلُ الَّذِي يَمْشِي خَلْفَهُ قَالَ هَذَا عَمُّهُ ‏ ‏أَبُو لَهَبٍ ‏ ‏قَالَ ‏ ‏عَبَّادٌ ‏ ‏أَظُنُّ بَيْنَ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏وَبَيْنَ ‏ ‏رَبِيعَةَ ‏ ‏مُحَمَّدَ بْنَ الْمُنْكَدِرِ ‏","","",""],[15448,15448,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سُلَيْمَانَ الضَّبِّيُّ دَاوُدُ بْنُ عَمْرِو بْنِ زُهَيْرٍ الْمُسَيِّبِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ عَبَّادٍ الدِّيلِيِّ ‏ ‏وَكَانَ جَاهِلِيًّا أَسْلَمَ ‏ ‏فَقَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَصَرَ عَيْنِي بِسُوقِ ‏ ‏ذِي الْمَجَازِ ‏ ‏يَقُولُ يَا أَيُّهَا النَّاسُ ‏ ‏قُولُوا لَا إِلَهَ إِلَّا اللَّهُ تُفْلِحُوا وَيَدْخُلُ فِي ‏ ‏فِجَاجِهَا ‏ ‏وَالنَّاسُ مُتَقَصِّفُونَ عَلَيْهِ فَمَا رَأَيْتُ أَحَدًا يَقُولُ شَيْئًا وَهُوَ لَا يَسْكُتُ يَقُولُ أَيُّهَا النَّاسُ قُولُوا لَا إِلَهَ إِلَّا اللَّهُ تُفْلِحُوا إِلَّا أَنَّ وَرَاءَهُ رَجُلًا أَحْوَلَ وَضِيءَ الْوَجْهِ ذَا ‏ ‏غَدِيرَتَيْنِ ‏ ‏يَقُولُ إِنَّهُ ‏ ‏صَابِئٌ ‏ ‏كَاذِبٌ فَقُلْتُ مَنْ هَذَا قَالُوا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَهُوَ يَذْكُرُ النُّبُوَّةَ قُلْتُ مَنْ هَذَا الَّذِي يُكَذِّبُهُ قَالُوا عَمُّهُ ‏ ‏أَبُو لَهَبٍ ‏ ‏قُلْتُ إِنَّكَ كُنْتَ يَوْمَئِذٍ صَغِيرًا ‏ ‏قَالَ ‏ ‏لَا وَاللَّهِ إِنِّي يَوْمَئِذٍ لَأَعْقِلُ ‏","","",""],[15449,15449,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي الرَّبِيعِ السَّمَّانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ سَلَمَةَ يَعْنِي ابْنَ أَبِي الْحُسَامِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏رَبِيعَةَ بْنَ عَبَّادٍ الدِّيلِيَّ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَطُوفُ عَلَى النَّاسِ ‏ ‏بمِنًى ‏ ‏فِي مَنَازِلِهِمْ قَبْلَ أَنْ يُهَاجِرَ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏يَقُولُ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَأْمُرُكُمْ أَنْ تَعْبُدُوهُ وَلَا تُشْرِكُوا بِهِ شَيْئًا قَالَ وَوَرَاءَهُ رَجُلٌ يَقُولُ هَذَا يَأْمُرُكُمْ أَنْ تَدَعُوا دِينَ آبَائِكُمْ فَسَأَلْتُ مَنْ هَذَا الرَّجُلُ فَقِيلَ هَذَا ‏ ‏أَبُو لَهَبٍ ‏","","",""],[15450,15450,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مَسْرُوقُ بْنُ الْمَرْزُبَانِ الْكُوفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏فَحَدَّثَنِي ‏ ‏حُسَيْنُ بْنُ عَبْدِ اللَّهِ بْنِ عُبَيْدِ اللَّهِ بْنِ الْعَبَّاسِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَبِيعَةَ بْنَ عَبَّادٍ الدِّيلِيَّ ‏ ‏قَالَ ‏ ‏إِنِّي لَمَعَ أَبِي رَجُلٌ شَابٌّ أَنْظُرُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتْبَعُ الْقَبَائِلَ وَوَرَاءَهُ رَجُلٌ أَحْوَلُ وَضِيءٌ ذُو ‏ ‏جُمَّةٍ ‏ ‏يَقِفُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْقَبِيلَةِ وَيَقُولُ يَا بَنِي فُلَانٍ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ ‏ ‏آمُرُكُمْ أَنْ تَعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَأَنْ تُصَدِّقُونِي حَتَّى أُنْفِذَ عَنْ اللَّهِ مَا بَعَثَنِي بِهِ فَإِذَا فَرَغَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ مَقَالَتِهِ قَالَ الْآخَرُ مِنْ خَلْفِهِ يَا بَنِي فُلَانٍ إِنَّ هَذَا يُرِيدُ مِنْكُمْ أَنْ تَسْلُخُوا ‏ ‏اللَّاتَ ‏ ‏وَالْعُزَّى ‏ ‏وَحُلَفَاءَكُمْ مِنْ الْحَيِّ ‏ ‏بَنِي مَالِكِ بْنِ أُقَيْشٍ ‏ ‏إِلَى مَا جَاءَ بِهِ مِنْ الْبِدْعَةِ وَالضَّلَالَةِ فَلَا تَسْمَعُوا لَهُ وَلَا تَتَّبِعُوهُ فَقُلْتُ لِأَبِي مَنْ هَذَا قَالَ عَمُّهُ ‏ ‏أَبُو لَهَبٍ ‏","","",""],[15451,15451,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ بَكَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَجُلًا يُقَالُ لَهُ ‏ ‏رَبِيعَةُ بْنُ عَبَّادٍ الدِّيلِيُّ ‏ ‏قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَمُرُّ فِي ‏ ‏فِجَاجِ ‏ ‏ذِي الْمَجَازِ ‏ ‏إِلَّا أَنَّهُمْ يَتْبَعُونَهُ وَقَالُوا هَذَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ وَرَجُلٌ أَحْوَلُ وَضِيءُ الْوَجْهِ ذُو ‏ ‏غَدِيرَتَيْنِ ‏ ‏يَتْبَعُهُ فِي ‏ ‏فِجَاجِ ‏ ‏ذِي الْمَجَازِ ‏ ‏وَيَقُولُ إِنَّهُ ‏ ‏صَابِئٌ ‏ ‏كَاذِبٌ فَقُلْتُ مَنْ هَذَا قَالُوا هَذَا ‏ ‏عَمُّهُ ‏ ‏أَبُو لَهَبٍ ‏","","",""],[15452,15452,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَحْيَى بْنِ سَعِيدٍ الْقُرَشِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حُسَيْنُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ عَبَّادٍ الدُؤَلِيِّ ‏ ‏وَعَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ عَبَّادٍ ‏ ‏قَالَ ‏ ‏وَاللَّهِ إِنِّي لَأَذْكُرُهُ يَطُوفُ عَلَى الْمَنَازِلِ ‏ ‏بِمِنًى ‏ ‏وَأَنَا مَعَ أَبِي غُلَامٌ شَابٌّ وَوَرَاءَهُ رَجُلٌ حَسَنُ الْوَجْهِ أَحْوَلُ ذُو ‏ ‏غَدِيرَتَيْنِ ‏ ‏فَلَمَّا وَقَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى قَوْمٍ قَالَ أَنَا رَسُولُ اللَّهِ ‏ ‏يَأْمُرُكُمْ أَنْ تَعْبُدُوهُ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَيَقُولُ الَّذِي خَلْفَهُ إِنَّ هَذَا يَدْعُوكُمْ إِلَى أَنْ تُفَارِقُوا دِينَ آبَائِكُمْ وَأَنْ تَسْلُخُوا ‏ ‏اللَّاتَ ‏ ‏وَالْعُزَّى ‏ ‏وَحُلَفَاءَكُمْ مِنْ ‏ ‏بَنِي مَالِكِ بْنِ أُقَيْشٍ ‏ ‏إِلَى مَا جَاءَ بِهِ مِنْ الْبِدْعَةِ وَالضَّلَالِ قَالَ فَقُلْتُ لِأَبِي مَنْ هَذَا قَالَ هَذَا عَمُّهُ ‏ ‏أَبُو لَهَبٍ عَبْدُ الْعُزَّى بْنُ عَبْدِ الْمُطَّلِبِ ‏","","",""],[15453,15453,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سُلَيْمَانَ بْنِ أَبِي حَثْمَةَ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏مُحَمَّدَ بْنَ مَسْلَمَةَ ‏ ‏يُطَارِدُ ‏ ‏امْرَأَةً ‏ ‏بِبَصَرِهِ فَقُلْتُ تَنْظُرُ إِلَيْهَا وَأَنْتَ مِنْ ‏ ‏أَصْحَابِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَلْقَى اللَّهُ عَزَّ وَجَلَّ فِي قَلْبِ امْرِئٍ خِطْبَةً لِامْرَأَةٍ فَلَا بَأْسَ أَنْ يَنْظُرَ إِلَيْهَا ‏","","",""],[15454,15454,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏قَالَ ‏ ‏مَرَرْتُ ‏ ‏بِالرَّبَذَةِ ‏ ‏فَإِذَا ‏ ‏فُسْطَاطٌ ‏ ‏فَقُلْتُ لِمَنْ هَذَا فَقِيلَ ‏ ‏لِمُحَمَّدِ بْنِ مَسْلَمَةَ ‏ ‏فَاسْتَأْذَنْتُ عَلَيْهِ فَدَخَلْتُ عَلَيْهِ فَقُلْتُ رَحِمَكَ اللَّهُ إِنَّكَ مِنْ هَذَا الْأَمْرِ بِمَكَانٍ فَلَوْ خَرَجْتَ إِلَى النَّاسِ فَأَمَرْتَ وَنَهَيْتَ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهُ سَتَكُونُ ‏ ‏فِتْنَةٌ ‏ ‏وَفُرْقَةٌ وَاخْتِلَافٌ فَإِذَا كَانَ ذَلِكَ فَأْتِ بِسَيْفِكَ ‏ ‏أُحُدًا ‏ ‏فَاضْرِبْ بِهِ عُرْضَهُ وَاكْسِرْ نَبْلَكَ وَاقْطَعْ وَتَرَكَ وَاجْلِسْ فِي بَيْتِكَ فَقَدْ كَانَ ذَلِكَ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏مَرَّةً فَاضْرِبْ بِهِ حَتَّى تَقْطَعَهُ ثُمَّ اجْلِسْ فِي بَيْتِكَ حَتَّى تَأْتِيَكَ يَدٌ خَاطِئَةٌ أَوْ يُعَافِيَكَ اللَّهُ عَزَّ وَجَلَّ فَقَدْ كَانَ ‏ ‏مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفَعَلْتُ مَا أَمَرَنِي بِهِ ثُمَّ اسْتَنْزَلَ سَيْفًا كَانَ مُعَلَّقًا بِعَمُودِ ‏ ‏الْفُسْطَاطِ ‏ ‏فَاخْتَرَطَهُ ‏ ‏فَإِذَا سَيْفٌ مِنْ خَشَبٍ فَقَالَ قَدْ فَعَلْتُ مَا أَمَرَنِي بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاتَّخَذْتُ هَذَا أُرْهِبُ بِهِ النَّاسَ قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏قَالَ ‏ ‏مَرَرْنَا ‏ ‏بِالرَّبَذَةِ ‏ ‏فَإِذَا ‏ ‏فُسْطَاطٌ ‏ ‏مَضْرُوبٌ ‏ ‏فَذَكَرَهُ قَالَ إِنَّهُ سَتَكُونُ ‏ ‏فِتْنَةٌ ‏ ‏وَفُرْقَةٌ فَاضْرِبْ بِسَيْفِكَ عُرْضَ ‏ ‏أُحُدٍ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏مَرَرْنَا ‏ ‏بِالرَّبَذَةِ ‏ ‏فَإِذَا ‏ ‏فُسْطَاطٌ ‏ ‏فَقُلْتُ لِمَنْ هَذَا ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[15455,15455,"","","‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ مَالِكٍ الْمُزَنِيُّ أَبُو جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَمِيلُ بْنُ زَيْدٍ ‏ ‏قَالَ ‏ ‏صَحِبْتُ شَيْخًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏ذَكَرَ أَنَّهُ كَانَتْ لَهُ صُحْبَةٌ يُقَالُ لَهُ ‏ ‏كَعْبُ بْنُ زَيْدٍ ‏ ‏أَوْ ‏ ‏زَيْدُ بْنُ كَعْبٍ ‏ ‏فَحَدَّثَنِي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَزَوَّجَ امْرَأَةً مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏فَلَمَّا دَخَلَ عَلَيْهَا وَضَعَ ثَوْبَهُ وَقَعَدَ عَلَى الْفِرَاشِ أَبْصَرَ ‏ ‏بِكَشْحِهَا ‏ ‏بَيَاضًا فَانْحَازَ عَنْ الْفِرَاشِ ثُمَّ قَالَ ‏ ‏خُذِي عَلَيْكِ ثِيَابَكِ وَلَمْ يَأْخُذْ مِمَّا أَتَاهَا شَيْئًا ‏","","",""],[15456,15456,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي يَعْقُوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي إِحْدَى صَلَاتَيْ الْعَشِيِّ الظُّهْرِ ‏ ‏أَوْ الْعَصْرِ ‏ ‏وَهُوَ ‏ ‏حَامِلٌ ‏ ‏الْحَسَنَ ‏ ‏أَوْ ‏ ‏الْحُسَيْنَ ‏ ‏فَتَقَدَّمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعَهُ ثُمَّ كَبَّرَ لِلصَّلَاةِ فَصَلَّى فَسَجَدَ بَيْنَ ‏ ‏ظَهْرَانَيْ ‏ ‏صَلَاتِهِ سَجْدَةً أَطَالَهَا فَقَالَ إِنِّي رَفَعْتُ رَأْسِي فَإِذَا الصَّبِيُّ عَلَى ظَهْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ سَاجِدٌ فَرَجَعْتُ فِي سُجُودِي فَلَمَّا قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ قَالَ النَّاسُ يَا رَسُولَ اللَّهِ إِنَّكَ سَجَدْتَ بَيْنَ ‏ ‏ظَهْرَانَيْ ‏ ‏صَلَاتِكَ هَذِهِ سَجْدَةً قَدْ أَطَلْتَهَا فَظَنَنَّا أَنَّهُ قَدْ حَدَثَ أَمْرٌ أَوْ أَنَّهُ قَدْ يُوحَى إِلَيْكَ قَالَ ‏ ‏فَكُلُّ ذَلِكَ لَمْ يَكُنْ وَلَكِنَّ ابْنِي ارْتَحَلَنِي فَكَرِهْتُ أَنْ أُعَجِّلَهُ حَتَّى يَقْضِيَ حَاجَتَهُ ‏","","",""],[15457,15457,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَمْزَةَ الْأَسْلَمِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّرَهُ عَلَى ‏ ‏سَرِيَّةٍ ‏ ‏فَخَرَجْتُ فِيهَا فَقَالَ ‏ ‏إِنْ أَخَذْتُمْ فُلَانًا فَأَحْرِقُوهُ بِالنَّارِ فَلَمَّا ‏ ‏وَلَّيْتُ ‏ ‏نَادَانِي فَقَالَ إِنْ أَخَذْتُمُوهُ فَاقْتُلُوهُ فَإِنَّهُ لَا يُعَذِّبُ بِالنَّارِ إِلَّا رَبُّ النَّارِ ‏","","",""],[15458,15458,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏زِيَادٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏أَنَّ ‏ ‏أَبَا الزِّنَادِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَنْظَلَةُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَمْرٍو الْأَسْلَمِيِّ صَاحِبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ وَرَهْطًا مَعَهُ إِلَى رَجُلٍ مِنْ ‏ ‏عُذْرَةَ ‏ ‏فَقَالَ إِنْ قَدَرْتُمْ عَلَى فُلَانٍ فَأَحْرِقُوهُ بِالنَّارِ فَانْطَلَقُوا حَتَّى إِذَا تَوَارَوْا مِنْهُ نَادَاهُمْ ‏ ‏أَوْ أَرْسَلَ فِي ‏ ‏أَثَرِهِمْ ‏ ‏فَرَدُّوهُمْ ثُمَّ قَالَ ‏ ‏إِنْ أَنْتُمْ قَدَرْتُمْ عَلَيْهِ فَاقْتُلُوهُ وَلَا تُحْرِقُوهُ بِالنَّارِ فَإِنَّمَا يُعَذِّبُ بِالنَّارِ رَبُّ النَّارِ قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏زِيَادٌ ‏ ‏أَنَّ ‏ ‏أَبَا الزِّنَادِ ‏ ‏أَخْبَرَهُ قَالَ أَخْبَرَنِي ‏ ‏حَنْظَلَةُ بْنُ عَلَيٍّ الْأَسْلَمِيُّ ‏ ‏أَنَّ ‏ ‏حَمْزَةَ بْنَ عَمْرٍو الْأَسْلَمِيَّ صَاحِبَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ وَرَهْطًا مَعَهُ ‏ ‏سَرِيَّةً ‏ ‏إِلَى رَجُلٍ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[15459,15459,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَمْرٍو الْأَسْلَمِيِّ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصَّوْمِ فِي السَّفَرِ فَقَالَ ‏ ‏إِنْ شِئْتَ صُمْتَ وَإِنْ شِئْتَ أَفْطَرْتَ ‏","","",""],[15460,15460,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَمْرٍو الْأَسْلَمِيِّ ‏ ‏أَنَّهُ رَأَى رَجُلًا عَلَى جَمَلٍ يَتْبَعُ رِحَالَ النَّاسِ ‏ ‏بِمِنًى ‏ ‏وَنَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَاهِدٌ وَالرَّجُلُ يَقُولُ ‏ ‏لَا تَصُومُوا هَذِهِ الْأَيَّامَ فَإِنَّهَا أَيَّامُ أَكْلٍ وَشُرْبٍ قَالَ ‏ ‏قَتَادَةُ ‏ ‏فَذَكَرَ لَنَا أَنَّ ذَلِكَ الْمُنَادِي كَانَ ‏ ‏بِلَالًا ‏","","",""],[15461,15461,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ حَمْزَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏عَلَى ظَهْرِ كُلِّ بَعِيرٍ شَيْطَانٌ فَإِذَا رَكِبْتُمُوهَا فَسَمُّوا اللَّهَ عَزَّ وَجَلَّ ثُمَّ لَا تُقَصِّرُوا عَنْ حَاجَاتِكُمْ ‏","","",""],[15462,15462,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏زَاذَانَ أَبِي عُمَرَ ‏ ‏عَنْ ‏ ‏عُلَيْمٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عَلَى سَطْحٍ مَعَنَا رَجُلٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَبْسًا الْغِفَارِيَّ ‏ ‏وَالنَّاسُ يَخُوضُونَ فِي الطَّاعُونِ فَقَالَ ‏ ‏عَبَسٌ ‏ ‏يَا طَاعُونُ خُذْنِي ثَلَاثًا يَقُولُهَا فَقَالَ لَهُ ‏ ‏عُلَيْمٌ ‏ ‏لِمَ تَقُولُ هَذَا أَلَمْ يَقُلْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَمَنَّى أَحَدُكُمْ الْمَوْتَ فَإِنَّهُ عِنْدَ انْقِطَاعِ عَمَلِهِ لَا يُرَدُّ فَيُسْتَعْتَبَ فَقَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ بَادِرُوا بِالْمَوْتِ سِتًّا ‏ ‏إِمْرَةَ ‏ ‏السُّفَهَاءِ ‏ ‏وَكَثْرَةَ ‏ ‏الشَّرْطِ ‏ ‏وَبَيْعَ الْحُكْمِ وَاسْتِخْفَافًا بِالدَّمِ وَقَطِيعَةَ ‏ ‏الرَّحِمِ ‏ ‏وَنَشْئًا يَتَّخِذُونَ الْقُرْآنَ مَزَامِيرَ يُقَدِّمُونَهُ ‏ ‏يُغَنِّيهِمْ وَإِنْ كَانَ أَقَلَّ ‏ ‏مِنْهُمْ فِقْهًا ‏","","",""],[15463,15463,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏شُقْرَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُهُ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَوَجِّهًا إِلَى ‏ ‏خَيْبَرَ ‏ ‏عَلَى حِمَارٍ ‏ ‏يُصَلِّي عَلَيْهِ ‏ ‏يُومِئُ ‏ ‏إِيمَاءً ‏","","",""],[15464,15464,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الْوَاحِدِ الْمَكِّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏بَلَغَنِي حَدِيثٌ عَنْ رَجُلٍ سَمِعَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاشْتَرَيْتُ بَعِيرًا ثُمَّ شَدَدْتُ عَلَيْهِ رَحْلِي فَسِرْتُ إِلَيْهِ شَهْرًا حَتَّى قَدِمْتُ عَلَيْهِ ‏ ‏الشَّامَ ‏ ‏فَإِذَا ‏ ‏عَبْدُ اللَّهِ بْنُ أُنَيْسٍ ‏ ‏فَقُلْتُ لِلْبَوَّابِ قُلْ لَهُ ‏ ‏جَابِرٌ ‏ ‏عَلَى الْبَابِ فَقَالَ ‏ ‏ابْنُ عَبْدِ اللَّهِ ‏ ‏قُلْتُ نَعَمْ فَخَرَجَ ‏ ‏يَطَأُ ‏ ‏ثَوْبَهُ فَاعْتَنَقَنِي وَاعْتَنَقْتُهُ فَقُلْتُ حَدِيثًا بَلَغَنِي عَنْكَ أَنَّكَ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْقِصَاصِ ‏ ‏فَخَشِيتُ أَنْ تَمُوتَ أَوْ أَمُوتَ قَبْلَ أَنْ أَسْمَعَهُ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ ‏ ‏أَوْ قَالَ الْعِبَادُ ‏ ‏عُرَاةً ‏ ‏غُرْلًا ‏ ‏بُهْمًا قَالَ قُلْنَا وَمَا بُهْمًا قَالَ لَيْسَ مَعَهُمْ شَيْءٌ ثُمَّ يُنَادِيهِمْ بِصَوْتٍ يَسْمَعُهُ مِنْ قُرْبٍ أَنَا الْمَلِكُ أَنَا الدَّيَّانُ وَلَا يَنْبَغِي لِأَحَدٍ مِنْ أَهْلِ النَّارِ أَنْ يَدْخُلَ النَّارَ وَلَهُ عِنْدَ أَحَدٍ مِنْ أَهْلِ الْجَنَّةِ حَقٌّ حَتَّى ‏ ‏أَقُصَّهُ ‏ ‏مِنْهُ وَلَا يَنْبَغِي لِأَحَدٍ مِنْ أَهْلِ الْجَنَّةِ أَنْ يَدْخُلَ الْجَنَّةَ وَلِأَحَدٍ مِنْ أَهْلِ النَّارِ عِنْدَهُ حَقٌّ حَتَّى ‏ ‏أَقُصَّهُ ‏ ‏مِنْهُ حَتَّى ‏ ‏اللَّطْمَةُ ‏ ‏قَالَ قُلْنَا كَيْفَ وَإِنَّا إِنَّمَا نَأْتِي اللَّهَ عَزَّ وَجَلَّ عُرَاةً ‏ ‏غُرْلًا ‏ ‏بُهْمًا قَالَ بِالْحَسَنَاتِ وَالسَّيِّئَاتِ ‏","","",""],[15465,15465,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدِ بْنِ الْمُهَاجِرِ بْنِ قُنْفُذٍ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أُنَيْسٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ أَكْبَرِ الْكَبَائِرِ الشِّرْكَ بِاللَّهِ ‏ ‏وَعُقُوقَ ‏ ‏الْوَالِدَيْنِ وَالْيَمِينَ ‏ ‏الْغَمُوسَ ‏ ‏وَمَا حَلَفَ حَالِفٌ بِاللَّهِ يَمِينًا ‏ ‏صَبْرًا ‏ ‏فَأَدْخَلَ فِيهَا مِثْلَ جَنَاحِ بَعُوضَةٍ إِلَّا جَعَلَهُ اللَّهُ ‏ ‏نُكْتَةً ‏ ‏فِي قَلْبِهِ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[15466,15466,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ يَعْنِي الْمَخْرَمِيَّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أُنَيْسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُمْ وَسَأَلُوهُ عَنْ لَيْلَةٍ يَتَرَاءَوْنَهَا فِي رَمَضَانَ قَالَ ‏ ‏لَيْلَةُ ثَلَاثٍ وَعِشْرِينَ ‏","","",""],[15467,15467,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ أَبُو ضَمْرَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أُنَيْسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ لَيْلَةَ الْقَدْرِ ثُمَّ أُنْسِيتُهَا ‏ ‏وَأُرَانِي صَبِيحَتَهَا أَسْجُدُ فِي مَاءٍ وَطِينٍ فَمُطِرْنَا لَيْلَةَ ثَلَاثٍ وَعِشْرِينَ فَصَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَانْصَرَفَ وَإِنَّ ‏ ‏أَثَرَ ‏ ‏الْمَاءِ وَالطِّينِ عَلَى جَبْهَتِهِ وَأَنْفِهِ ‏","","",""],[15468,15468,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُعَاذُ بْنُ عَبْدِ اللَّهِ بْنِ خُبَيْبٍ الْجُهَنِيُّ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ خُبَيْبٍ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ فِي زَمَانِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَدْ سَأَلَهُ فَأَعْطَاهُ قَالَ جَلَسَ مَعَنَا ‏ ‏عَبْدُ اللَّهُ بْنُ أُنَيْسٍ صَاحِبُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَجْلِسِهِ فِي مَجْلِسِ ‏ ‏جُهَيْنَةَ ‏ ‏قَالَ فِي رَمَضَانَ قَالَ فَقُلْنَا لَهُ يَا ‏ ‏أَبَا يَحْيَى ‏ ‏سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذِهِ اللَّيْلَةِ الْمُبَارَكَةِ مِنْ شَيْءٍ فَقَالَ نَعَمْ جَلَسْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي آخِرِ هَذَا الشَّهْرِ فَقُلْنَا لَهُ يَا رَسُولَ اللَّهِ مَتَى نَلْتَمِسُ هَذِهِ اللَّيْلَةَ الْمُبَارَكَةَ قَالَ ‏ ‏الْتَمِسُوهَا ‏ ‏هَذِهِ اللَّيْلَةَ وَقَالَ وَذَلِكَ مَسَاءَ لَيْلَةِ ثَلَاثٍ وَعِشْرِينَ فَقَالَ لَهُ رَجُلٌ مِنْ الْقَوْمِ وَهِيَ إِذًا يَا رَسُولَ اللَّهِ أَوَّلُ ثَمَانٍ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا لَيْسَتْ بِأَوَّلِ ثَمَانٍ وَلَكِنَّهَا أَوَّلُ ‏ ‏السَّبْعِ إِنَّ الشَّهْرَ لَا يَتِمُّ ‏","","",""],[15469,15469,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبْدِ اللَّهِ بْنِ أُنَيْسٍ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّهُ قَدْ بَلَغَنِي أَنَّ ‏ ‏خَالِدَ بْنَ سُفْيَانَ بْنِ نُبَيْحٍ ‏ ‏يَجْمَعُ لِي النَّاسَ لِيَغْزُوَنِي وَهُوَ ‏ ‏بِعُرَنَةَ ‏ ‏فَأْتِهِ فَاقْتُلْهُ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ انْعَتْهُ لِي حَتَّى أَعْرِفَهُ قَالَ إِذَا رَأَيْتَهُ وَجَدْتَ لَهُ ‏ ‏أُقْشَعْرِيَرَةً ‏ ‏قَالَ فَخَرَجْتُ ‏ ‏مُتَوَشِّحًا ‏ ‏بِسَيْفِي حَتَّى وَقَعْتُ عَلَيْهِ وَهُوَ ‏ ‏بِعُرَنَةَ ‏ ‏مَعَ ‏ ‏ظُعُنٍ ‏ ‏يَرْتَادُ ‏ ‏لَهُنَّ مَنْزِلًا وَحِينَ كَانَ وَقْتُ الْعَصْرِ فَلَمَّا رَأَيْتُهُ وَجَدْتُ مَا وَصَفَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْأُقْشَعْرِيرَةِ ‏ ‏فَأَقْبَلْتُ نَحْوَهُ وَخَشِيتُ أَنْ يَكُونَ بَيْنِي وَبَيْنَهُ مُحَاوَلَةٌ تَشْغَلُنِي عَنْ الصَّلَاةِ فَصَلَّيْتُ وَأَنَا أَمْشِي نَحْوَهُ ‏ ‏أُومِئُ ‏ ‏بِرَأْسِي الرُّكُوعَ وَالسُّجُودَ فَلَمَّا انْتَهَيْتُ إِلَيْهِ قَالَ مَنْ الرَّجُلُ قُلْتُ رَجُلٌ مِنْ ‏ ‏الْعَرَبِ ‏ ‏سَمِعَ بِكَ وَبِجَمْعِكَ لِهَذَا الرَّجُلِ فَجَاءَكَ لِهَذَا قَالَ أَجَلْ أَنَا فِي ذَلِكَ قَالَ فَمَشَيْتُ مَعَهُ شَيْئًا حَتَّى إِذَا أَمْكَنَنِي حَمَلْتُ عَلَيْهِ السَّيْفَ حَتَّى قَتَلْتُهُ ثُمَّ خَرَجْتُ وَتَرَكْتُ ‏ ‏ظَعَائِنَهُ ‏ ‏مُكِبَّاتٍ عَلَيْهِ فَلَمَّا قَدِمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَآنِي فَقَالَ أَفْلَحَ الْوَجْهُ قَالَ قُلْتُ قَتَلْتُهُ يَا رَسُولَ اللَّهِ قَالَ صَدَقْتَ قَالَ ثُمَّ قَامَ مَعِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ فِي بَيْتِهِ فَأَعْطَانِي عَصًا فَقَالَ أَمْسِكْ هَذِهِ عِنْدَكَ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ أُنَيْسٍ ‏ ‏قَالَ فَخَرَجْتُ بِهَا عَلَى النَّاسِ فَقَالُوا مَا هَذِهِ الْعَصَا قَالَ قُلْتُ أَعْطَانِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَرَنِي أَنْ أَمْسِكَهَا قَالُوا أَوَلَا تَرْجِعُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَسْأَلَهُ عَنْ ذَلِكَ قَالَ فَرَجَعْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ لِمَ أَعْطَيْتَنِي هَذِهِ الْعَصَا قَالَ ‏ ‏آيَةٌ ‏ ‏بَيْنِي وَبَيْنَكَ يَوْمَ الْقِيَامَةِ إِنَّ أَقَلَّ النَّاسِ الْمُتَخَصِّرُونَ يَوْمَئِذٍ يَوْمَ الْقِيَامَةِ ‏ ‏فَقَرَنَهَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏بِسَيْفِهِ فَلَمْ تَزَلْ مَعَهُ حَتَّى إِذَا مَاتَ أَمَرَ بِهَا فَصُبَّتْ مَعَهُ فِي كَفَنِهِ ثُمَّ دُفِنَا جَمِيعًا ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏بَعْضِ وَلَدِ عَبْدِ اللَّهِ بْنِ أُنَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ بْنِ أُنَيْسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ إِلَى ‏ ‏خَالِدِ بْنِ سُفْيَانَ بْنِ نُبَيْحٍ الْهُذَلِيِّ ‏ ‏لِيَقْتُلَهُ وَكَانَ يُجَمِّعُ لِقِتَالِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَتَيْتُهُ ‏ ‏بِعُرَنَةَ ‏ ‏وَهُوَ فِي ‏ ‏ظَهْرٍ ‏ ‏لَهُ وَقَدْ دَخَلَ وَقْتُ الْعَصْرِ فَخِفْتُ أَنْ يَكُونَ بَيْنِي وَبَيْنَهُ مُحَاوَلَةٌ تَشْغَلُنِي عَنْ الصَّلَاةِ قَالَ فَصَلَّيْتُ وَأَنَا أَمْشِي أُومِئُ ‏ ‏إِيمَاءً ‏ ‏فَلَمَّا انْتَهَيْتُ إِلَيْهِ قُلْتُ كَذَا وَكَذَا حَتَّى ذَكَرَ الْحَدِيثَ ثُمَّ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ بِقَتْلِهِ إِيَّاهُ وَذَكَرَ الْحَدِيثَ ‏","","",""],[15470,15470,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي أُسَيْدٍ السَّاعِدِيِّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُسَيْدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏بَنُو النَّجَّارِ ‏ ‏ثُمَّ ‏ ‏بَنُو عَبْدِ الْأَشْهَلِ ‏ ‏ثُمَّ ‏ ‏بَنُو الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏ثُمَّ ‏ ‏بَنُو سَاعِدَةَ ‏ ‏وَفِي كُلِّ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏خَيْرٌ ‏ ‏فَقَالَ ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏مَا أَرَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا قَدْ فَضَّلَ عَلَيْنَا فَقِيلَ قَدْ فَضَّلَكُمْ عَلَى كَثِيرٍ ‏","","",""],[15471,15471,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي أُسَيْدٍ السَّاعِدِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ ‏ ‏الْأَنْصَارِ ‏ ‏بَنُو النَّجَّارِ ‏ ‏ثُمَّ ‏ ‏بَنُو عَبْدِ الْأَشْهَلِ ‏ ‏ثُمَّ ‏ ‏بَنُو الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏ثُمَّ ‏ ‏بَنُو سَاعِدَةَ ‏ ‏ثُمَّ قَالَ وَفِي كُلِّ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏خَيْرٌ ‏","","",""],[15472,15472,"","","‏ ‏قَالَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي أُسَيْدٍ السَّاعِدِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏بَنُو النَّجَّارِ ‏ ‏ثُمَّ ‏ ‏بَنُو عَبْدِ الْأَشْهَلِ ‏ ‏ثُمَّ ‏ ‏بَنُو الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏ثُمَّ ‏ ‏بَنُو سَاعِدَةَ ‏ ‏ثُمَّ قَالَ وَفِي كُلِّ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏خَيْرٌ ‏ ‏فَقَالَ ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏جَعَلَنَا رَابِعَ أَرْبَعَةٍ أَسْرِجُوا لِي حِمَارِي فَقَالَ ابْنُ أَخِيهِ أَتُرِيدُ أَنْ تَرُدَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَسْبُكَ ‏ ‏أَنْ تَكُونَ رَابِعَ أَرْبَعَةٍ ‏","","",""],[15473,15473,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي أُسَيْدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ ‏ ‏الْأَنْصَارِ ‏ ‏بَنُو النَّجَّارِ ‏ ‏ثُمَّ ‏ ‏بَنُو عَبْدِ الْأَشْهَلِ ‏ ‏ثُمَّ ‏ ‏بَنُو الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏ثُمَّ ‏ ‏بَنُو سَاعِدَةَ ‏ ‏وَفِي كُلِّ ‏ ‏الْأَنْصَارِ ‏ ‏خَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرْبٌ يَعْنِي ابْنَ شَدَّادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا أُسَيْدٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ خَيْرُ دِيَارِ ‏ ‏الْأَنْصَارِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[15474,15474,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَطَاءٌ ‏ ‏رَجُلٌ كَانَ يَكُونُ بِالسَّاحِلِ ‏ ‏عَنْ ‏ ‏أَبِي أُسَيْدٍ ‏ ‏أَوْ ‏ ‏أَبِي أَسِيدِ بْنِ ثَابِتٍ ‏ ‏شَكَّ ‏ ‏سُفْيَانُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُوا الزَّيْتَ وَادَّهِنُوا بِالزَّيْتِ فَإِنَّهُ مِنْ شَجَرَةٍ مُبَارَكَةٍ ‏","","",""],[15475,15475,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ الشَّامِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُوا الزَّيْتَ وَادَّهِنُوا بِهِ فَإِنَّهُ مِنْ شَجَرَةٍ مُبَارَكَةٍ ‏","","",""],[15476,15476,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏أَنَّ ‏ ‏أَبَا أُسَيْدٍ ‏ ‏كَانَ ‏ ‏يَقُولُ ‏ ‏أَصَبْتُ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏سَيْفَ ‏ ‏ابْنِ عَابِدٍ الْمَرْزُبَانِ ‏ ‏فَلَمَّا أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَرُدُّوا مَا فِي أَيْدِيهِمْ أَقْبَلْتُ بِهِ حَتَّى أَلْقَيْتُهُ فِي ‏ ‏النَّفْلِ ‏ ‏قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمْنَعُ شَيْئًا يُسْأَلُهُ قَالَ فَعَرَفَهُ ‏ ‏الْأَرْقَمُ بْنُ أَبِي الْأَرْقَمِ الْمَخْزُومِيُّ ‏ ‏فَسَأَلَهُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْطَاهُ إِيَّاهُ ‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏يَعْقُوبَ ‏ ‏فِي مَغَازِي ‏ ‏أَبِيهِ ‏ ‏أَوْ سَمَاعٌ ‏ ‏قَالَ ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَعْضُ ‏ ‏بَنِي سَاعِدَةَ ‏ ‏عَنْ ‏ ‏أَبِي أُسَيْدٍ مَالِكِ بْنِ رَبِيعَةَ ‏ ‏قَالَ ‏ ‏أَصَبْتُ سَيْفَ ‏ ‏بَنِي عَابِدٍ الْمَخْزُومِيِّينَ الْمَرْزُبَانِ ‏ ‏يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَلَمَّا أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسَ أَنْ يُؤَدُّوا مَا فِي أَيْدِيهِمْ مِنْ ‏ ‏النَّفْلِ ‏ ‏أَقْبَلْتُ بِهِ حَتَّى أَلْقَيْتُهُ فِي ‏ ‏النَّفْلِ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمْنَعُ شَيْئًا يُسْأَلُهُ فَعَرَفَهُ ‏ ‏الْأَرْقَمُ بْنُ أَبِي الْأَرْقَمِ ‏ ‏فَسَأَلَهُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْطَاهُ إِيَّاهُ ‏","","",""],[15477,15477,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ سَعِيدِ بْنِ سُوَيْدٍ الْأَنْصَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حُمَيْدٍ ‏ ‏وَأَبَا أُسَيْدٍ ‏ ‏يَقُولَانِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ الْمَسْجِدَ فَلْيَقُلْ اللَّهُمَّ افْتَحْ لَنَا أَبْوَابَ رَحْمَتِكَ وَإِذَا خَرَجَ فَلْيَقُلْ اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ ‏","","",""],[15478,15478,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ سَعِيدِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ ‏ ‏وَعَنْ ‏ ‏أَبِي أُسَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ الْحَدِيثَ عَنِّي تَعْرِفُهُ قُلُوبُكُمْ وَتَلِينُ لَهُ أَشْعَارُكُمْ وَأَبْشَارُكُمْ وَتَرَوْنَ أَنَّهُ مِنْكُمْ قَرِيبٌ فَأَنَا أَوْلَاكُمْ بِهِ وَإِذَا سَمِعْتُمْ الْحَدِيثَ عَنِّي تُنْكِرُهُ قُلُوبُكُمْ وَتَنْفِرُ أَشْعَارُكُمْ وَأَبْشَارُكُمْ وَتَرَوْنَ أَنَّهُ مِنْكُمْ بَعِيدٌ فَأَنَا أَبْعَدُكُمْ مِنْهُ ‏","","",""],[15479,15479,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْغَسِيلِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَسِيدُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَلِيِّ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي أُسَيْدٍ صَاحِبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ بَدْرِيًّا وَكَانَ مَوْلَاهُمْ قَالَ قَالَ ‏ ‏أَبُو أُسَيْدٍ ‏ ‏بَيْنَمَا أَنَا جَالِسٌ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ جَاءَهُ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ هَلْ بَقِيَ عَلَيَّ مِنْ بِرِّ أَبَوَيَّ شَيْءٌ بَعْدَ مَوْتِهِمَا أَبَرُّهُمَا بِهِ قَالَ نَعَمْ خِصَالٌ أَرْبَعَةٌ ‏ ‏الصَّلَاةُ عَلَيْهِمَا ‏ ‏وَالِاسْتِغْفَارُ لَهُمَا وَإِنْفَاذُ عَهْدِهِمَا وَإِكْرَامُ صَدِيقِهِمَا وَصِلَةُ الرَّحِمِ الَّتِي لَا رَحِمَ لَكَ إِلَّا مِنْ قِبَلِهِمَا فَهُوَ الَّذِي بَقِيَ عَلَيْكَ مِنْ بِرِّهِمَا بَعْدَ مَوْتِهِمَا ‏","","",""],[15480,15480,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْغَسِيلِ ‏ ‏عَنْ ‏ ‏عَبَّاسِ بْنِ سَهْلٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ أَبِي أُسَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏لَمَّا الْتَقَيْنَا نَحْنُ وَالْقَوْمُ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ لَنَا ‏ ‏إِذَا ‏ ‏أَكْثَبُوكُمْ ‏ ‏يَعْنِي ‏ ‏غَشُوكُمْ ‏ ‏فَارْمُوهُمْ بِالنَّبْلِ ‏ ‏وَأُرَاهُ قَالَ وَاسْتَبْقُوا نَبْلَكُمْ ‏","","",""],[15481,15481,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْغَسِيلِ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ أَبِي أُسَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَعَبَّاسِ بْنِ سَهْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَا ‏ ‏مَرَّ بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابٌ لَهُ فَخَرَجْنَا مَعَهُ حَتَّى انْطَلَقْنَا إِلَى ‏ ‏حَائِطٍ ‏ ‏يُقَالُ لَهُ الشَّوْطُ حَتَّى انْتَهَيْنَا إِلَى ‏ ‏حَائِطَيْنِ ‏ ‏مِنْهُمَا فَجَلَسْنَا بَيْنَهُمَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْلِسُوا وَدَخَلَ هُوَ وَقَدْ أُوتِيَ ‏ ‏بِالْجَوْنِيَّةِ ‏ ‏فِي بَيْتِ ‏ ‏أُمَيْمَةَ بِنْتِ النُّعْمَانِ بْنِ شَرَاحِيلَ ‏ ‏وَمَعَهَا دَايَةٌ لَهَا فَلَمَّا دَخَلَ عَلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَبِي لِي نَفْسَكِ قَالَتْ وَهَلْ تَهَبُ الْمَلِكَةُ نَفْسَهَا لِلسُّوقَةِ قَالَتْ إِنِّي أَعُوذُ بِاللَّهِ مِنْكَ قَالَ لَقَدْ عُذْتِ بِمُعَاذٍ ثُمَّ خَرَجَ عَلَيْنَا فَقَالَ يَا ‏ ‏أَبَا أُسَيْدٍ ‏ ‏اكْسُهَا ‏ ‏رَازِقِيَّتَيْنِ ‏ ‏وَأَلْحِقْهَا بِأَهْلِهَا ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏غَيْرُ ‏ ‏أَبِي أَحْمَدَ ‏ ‏امْرَأَةٌ مِنْ ‏ ‏بَنِي الْجَوْنِ ‏ ‏يُقَالُ لَهَا ‏ ‏أَمِينَةُ ‏","","",""],[15482,15482,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَهْلًا ‏ ‏يَقُولُ ‏ ‏أَتَى ‏ ‏أَبُو أُسَيْدٍ السَّاعِدِيُّ ‏ ‏فَدَعَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي عُرْسِهِ فَكَانَتْ امْرَأَتُهُ خَادِمَهُمْ يَوْمَئِذٍ وَهِيَ الْعَرُوسُ قَالَ تَدْرُونَ مَا سَقَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْقَعَتْ ‏ ‏تَمَرَاتٍ مِنْ اللَّيْلَةِ فِي ‏ ‏تَوْرٍ ‏","","",""],[15483,15483,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏مُوسَى بْنَ جُبَيْرٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ الْحُبَابِ الْأَنْصَارِيَّ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ أُنَيْسٍ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُمْ تَذَاكَرُوا هُوَ ‏ ‏وَعُمَرُ بْنُ الْخَطَّابِ ‏ ‏يَوْمًا ‏ ‏الصَّدَقَةَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏أَلَمْ تَسْمَعْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ ذَكَرَ ‏ ‏غُلُولَ ‏ ‏الصَّدَقَةِ ‏ ‏إِنَّهُ ‏ ‏مَنْ ‏ ‏غَلَّ ‏ ‏مِنْهَا ‏ ‏بَعِيرًا أَوْ شَاةً أُتِيَ بِهِ يَحْمِلُهُ يَوْمَ الْقِيَامَةِ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ أُنَيْسٍ ‏ ‏بَلَى ‏","","",""],[15484,15484,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَبِيبُ بْنُ غَرْقَدَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَمْرِو بْنِ الْأَحْوَصِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ ‏ ‏شَهِدَ حَجَّةَ الْوَدَاعِ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَجْنِي جَانٍ إِلَّا عَلَى نَفْسِهِ لَا ‏ ‏يَجْنِي وَالِدٌ عَلَى وَلَدِهِ وَلَا مَوْلُودٌ عَلَى وَالِدِهِ ‏","","",""],[15485,15485,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمُ بْنُ خَارِجَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَيُّوبَ بْنِ مَيْسَرَةَ بْنِ حَلْبَسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏سَمِعَ ‏ ‏خُرَيْمَ بْنَ فَاتِكٍ الْأَسَدِيَّ ‏ ‏يَقُولُ ‏ ‏أَهْلُ ‏ ‏الشَّامِ ‏ ‏سَوْطُ اللَّهِ فِي الْأَرْضِ يَنْتَقِمُ بِهِمْ مِمَّنْ يَشَاءُ كَيْفَ يَشَاءُ وَحَرَامٌ عَلَى مُنَافِقِيهِمْ أَنْ يَظْهَرُوا عَلَى مُؤْمِنِيهِمْ وَلَنْ يَمُوتُوا إِلَّا هَمًّا أَوْ غَيْظًا أَوْ حُزْنًا ‏","","",""],[15486,15486,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمُ بْنُ خَارِجَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏طَيَّافٌ الْإِسْكَنْدَرَانِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ شَرَاحِيلَ بْنِ بُكَيْلٍ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏شُرَاحْبِيلَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏إِنَّ لِي أَرْحَامًا ‏ ‏بِمِصْرَ ‏ ‏يَتَّخِذُونَ مِنْ هَذِهِ الْأَعْنَابِ قَالَ وَفَعَلَ ذَلِكَ أَحَدٌ مِنْ الْمُسْلِمِينَ قُلْتُ نَعَمْ قَالَ ‏ ‏لَا تَكُونُوا بِمَنْزِلَةِ ‏ ‏الْيَهُودِ ‏ ‏حُرِّمَتْ عَلَيْهِمْ الشُّحُومُ فَبَاعُوهَا وَأَكَلُوا أَثْمَانَهَا قَالَ قُلْتُ مَا تَقُولُ فِي رَجُلٍ أَخَذَ عُنْقُودًا فَعَصَرَهُ فَشَرِبَهُ قَالَ لَا بَأْسَ فَلَمَّا نَزَلْتُ قَالَ مَا حَلَّ شُرْبُهُ حَلَّ بَيْعُهُ ‏","","",""],[15487,15487,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَيْمُونٍ الْأَشْعَرِيُّ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏رَفَعَهُ قَالَ ‏ ‏أَيُّمَا شَجَرَةٍ أَظَلَّتْ عَلَى قَوْمٍ فَصَاحِبُهُ بِالْخِيَارِ مِنْ قَطْعِ مَا أَظَلَّ أَوْ أَكْلِ ثَمَرِهَا ‏","","",""],[15488,15488,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْمُنْكَدِرُ بْنُ مُحَمَّدٍ يَعْنِي ابْنَ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ التَّيْمِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِمًا فِي السُّوقِ يَوْمَ الْعِيدِ يَنْظُرُ وَالنَّاسُ يَمُرُّونَ ‏","","",""],[15489,15489,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ خَالَدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ ‏ ‏قَالَ ‏ ‏ذَكَرَ طَبِيبٌ الدَّوَاءَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذَكَرَ الضُّفْدَعَ تَكُونُ فِي الدَّوَاءِ فَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قَتْلِهَا ‏","","",""],[15490,15490,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏وَهَارُونُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ حَاطِبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ التَّيْمِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏لُقَطَةِ ‏ ‏الْحَاجِّ ‏ ‏وَقَالَ ‏ ‏هَارُونُ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ ‏","","",""],[15491,15491,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عِلْبَاءَ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَقُومُ السَّاعَةُ إِلَّا عَلَى ‏ ‏حُثَالَةِ ‏ ‏النَّاسِ ‏","","",""],[15492,15492,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ النُّعْمَانِ بْنِ مَعْبَدِ بْنِ هَوْذَةَ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏بِالْإِثْمِدِ ‏ ‏الْمُرَوَّحِ ‏ ‏عِنْدَ النَّوْمِ ‏","","",""],[15493,15493,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَاه ‏ ‏أَبِي ‏ ‏عَنْهُ وَهُوَ حَيٌّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُجْرُ بْنُ الْحَارِثِ الْغَسَّانِيُّ ‏ ‏مِنْ أَهْلِ ‏ ‏الرَّمْلَةِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَوْنٍ الْكِنَانِيِّ ‏ ‏وَكَانَ عَامِلًا ‏ ‏لِعُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَلَى ‏ ‏الرَّمْلَةِ ‏ ‏أَنَّهُ ‏ ‏شَهِدَ ‏ ‏عَبْدَ الْمَلِكِ بْنَ مَرْوَانَ ‏ ‏قَالَ ‏ ‏لِبَشِيرِ بْنِ عَقْرَبَةَ الْجُهَنِيِّ ‏ ‏يَوْمَ قُتِلَ ‏ ‏عَمْرُو بْنُ سَعِيدِ بْنِ الْعَاصِ ‏ ‏يَا ‏ ‏أَبَا الْيَمَانِ ‏ ‏إِنِّي قَدْ احْتَجْتُ الْيَوْمَ إِلَى كَلَامِكَ فَقُمْ فَتَكَلَّمْ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قَامَ يَخْطُبُ لَا ‏ ‏يَلْتَمِسُ ‏ ‏بِهَا إِلَّا ‏ ‏رِيَاءً ‏ ‏وَسُمْعَةً ‏ ‏أَوْقَفَهُ اللَّهُ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ مَوْقِفَ ‏ ‏رِيَاءٍ ‏ ‏وَسُمْعَةٍ ‏","","",""],[15494,15494,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ مَيْمُونٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبِيعَةَ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ خَالِدٍ السُّلَمِيِّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏آخَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ رَجُلَيْنِ قُتِلَ أَحَدُهُمَا عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ مَاتَ الْآخَرُ فَصَلَّوْا عَلَيْهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قُلْتُمْ قَالَ قُلْنَا اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ اللَّهُمَّ أَلْحِقْهُ بِصَاحِبِهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَيْنَ صَلَاتُهُ بَعْدَ صَلَاتِهِ وَأَيْنَ صِيَامُهُ ‏ ‏أَوْ عَمَلُهُ بَعْدَ عَمَلِهِ ‏ ‏مَا بَيْنَهُمَا أَبْعَدُ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏","","",""],[15495,15495,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ كَعْبِ بْنِ مَالِكٍ الْأَنْصَارِيُّ ‏ ‏وَهُوَ أَحَدُ الثَّلَاثَةِ الَّذِينَ تِيبَ عَلَيْهِمْ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏بَعْضُ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ يَوْمًا عَاصِبًا رَأْسَهُ فَقَالَ فِي خُطْبَتِهِ أَمَّا بَعْدُ يَا مَعْشَرَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏فَإِنَّكُمْ قَدْ أَصْبَحْتُمْ تَزِيدُونَ وَأَصْبَحَتْ ‏ ‏الْأَنْصَارُ ‏ ‏لَا تَزِيدُ عَلَى هَيْئَتِهَا الَّتِي هِيَ عَلَيْهَا الْيَوْمَ وَإِنَّ ‏ ‏الْأَنْصَارَ ‏ ‏عَيْبَتِي ‏ ‏الَّتِي أَوَيْتُ إِلَيْهَا فَأَكْرِمُوا كَرِيمَهُمْ ‏ ‏وَتَجَاوَزُوا ‏ ‏عَنْ مُسِيئِهِمْ ‏","","",""],[15496,15496,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي الْوَاسِطِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ أَبِي زِيَادٍ ‏ ‏مَوْلَى ‏ ‏بَنِي مَخْزُومٍ ‏ ‏عَنْ ‏ ‏خَادِمٍ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٍ أَوْ امْرَأَةٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّا يَقُولُ لِلْخَادِمِ أَلَكَ حَاجَةٌ قَالَ حَتَّى كَانَ ذَاتَ يَوْمٍ فَقَالَ يَا رَسُولَ اللَّهِ حَاجَتِي قَالَ وَمَا حَاجَتُكَ قَالَ ‏ ‏حَاجَتِي أَنْ تَشْفَعَ لِي يَوْمَ الْقِيَامَةِ قَالَ وَمَنْ دَلَّكَ عَلَى هَذَا قَالَ رَبِّي قَالَ إِمَّا لَا فَأَعِنِّي بِكَثْرَةِ السُّجُودِ ‏","","",""],[15497,15497,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى أَبُو عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْفَضْلِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرٍو الضَّمْرِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَدِيِّ بْنِ الْخِيَارِ ‏ ‏إِلَى ‏ ‏الشَّامِ ‏ ‏فَلَمَّا قَدِمْنَا ‏ ‏حِمْصَ ‏ ‏قَالَ لِي ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏هَلْ لَكَ فِي ‏ ‏وَحْشِيٍّ ‏ ‏نَسْأَلُهُ عَنْ قَتْلِ ‏ ‏حَمْزَةَ ‏ ‏قُلْتُ نَعَمْ وَكَانَ ‏ ‏وَحْشِيٌّ ‏ ‏يَسْكُنُ ‏ ‏حِمْصَ ‏ ‏قَالَ فَسَأَلْنَا عَنْهُ فَقِيلَ لَنَا هُوَ ذَاكَ فِي ظِلِّ قَصْرِهِ كَأَنَّهُ ‏ ‏حَمِيتٌ ‏ ‏قَالَ فَجِئْنَا حَتَّى وَقَفْنَا عَلَيْهِ فَسَلَّمْنَا فَرَدَّ عَلَيْنَا السَّلَامَ قَالَ ‏ ‏وَعُبَيْدُ اللَّهِ ‏ ‏مُعْتَجِرٌ ‏ ‏بِعِمَامَتِهِ مَا يَرَى ‏ ‏وَحْشِيٌّ ‏ ‏إِلَّا عَيْنَيْهِ وَرِجْلَيْهِ فَقَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏يَا ‏ ‏وَحْشِيُّ ‏ ‏أَتَعْرِفُنِي قَالَ فَنَظَرَ إِلَيْهِ ثُمَّ قَالَ لَا وَاللَّهِ إِلَّا أَنِّي أَعْلَمُ أَنَّ ‏ ‏عَدِيَّ بْنَ الْخِيَارِ ‏ ‏تَزَوَّجَ امْرَأَةً يُقَالُ لَهَا ‏ ‏أُمُّ قِتَالٍ ‏ ‏ابْنَةُ ‏ ‏أَبِي الْعِيصِ ‏ ‏فَوَلَدَتْ لَهُ غُلَامًا ‏ ‏بِمَكَّةَ ‏ ‏فَاسْتَرْضَعَهُ فَحَمَلْتُ ذَلِكَ الْغُلَامَ مَعَ أُمِّهِ فَنَاوَلْتُهَا إِيَّاهُ فَلَكَأَنِّي نَظَرْتُ إِلَى قَدَمَيْكَ قَالَ فَكَشَفَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏وَجْهَهُ ثُمَّ قَالَ أَلَا تُخْبِرُنَا بِقَتْلِ ‏ ‏حَمْزَةَ ‏ ‏قَالَ نَعَمْ إِنَّ ‏ ‏حَمْزَةَ ‏ ‏قَتَلَ ‏ ‏طُعَيْمَةَ بْنَ عَدِيٍّ ‏ ‏بِبَدْرٍ ‏ ‏فَقَالَ لِي ‏ ‏مَوْلَايَ ‏ ‏جُبَيْرُ بْنُ مُطْعِمٍ ‏ ‏إِنْ قَتَلْتَ ‏ ‏حَمْزَةَ ‏ ‏بِعَمِّي فَأَنْتَ حُرٌّ فَلَمَّا خَرَجَ النَّاسُ يَوْمَ ‏ ‏عِينِينَ ‏ ‏قَالَ ‏ ‏وَعِينِينُ ‏ ‏جُبَيْلٌ تَحْتَ ‏ ‏أُحُدٍ ‏ ‏وَبَيْنَهُ وَادٍ خَرَجْتُ مَعَ النَّاسِ إِلَى الْقِتَالِ فَلَمَّا أَنْ اصْطَفُّوا لِلْقِتَالِ قَالَ خَرَجَ ‏ ‏سِبَاعٌ ‏ ‏مَنْ مُبَارِزٌ قَالَ فَخَرَجَ إِلَيْهِ ‏ ‏حَمْزَةُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏فَقَالَ ‏ ‏سِبَاعُ بْنُ أُمِّ أَنْمَارٍ ‏ ‏يَا ‏ ‏ابْنَ مُقَطِّعَةِ ‏ ‏الْبُظُورِ ‏ ‏أَتُحَادُّ اللَّهَ وَرَسُولَهُ ثُمَّ شَدَّ عَلَيْهِ فَكَانَ ‏ ‏كَأَمْسِ الذَّاهِبِ ‏ ‏وَأَكْمَنْتُ ‏ ‏لِحَمْزَةَ ‏ ‏تَحْتَ صَخْرَةٍ حَتَّى إِذَا مَرَّ عَلَيَّ فَلَمَّا أَنْ ‏ ‏دَنَا ‏ ‏مِنِّي رَمَيْتُهُ بِحَرْبَتِي فَأَضَعُهَا فِي ‏ ‏ثُنَّتِهِ ‏ ‏حَتَّى خَرَجَتْ مِنْ بَيْنِ وَرِكَيْهِ قَالَ فَكَانَ ذَلِكَ الْعَهْدُ بِهِ قَالَ فَلَمَّا رَجَعَ النَّاسُ رَجَعْتُ مَعَهُمْ قَالَ فَأَقَمْتُ ‏ ‏بِمَكَّةَ ‏ ‏حَتَّى ‏ ‏فَشَا ‏ ‏فِيهَا الْإِسْلَامُ قَالَ ثُمَّ خَرَجْتُ إِلَى ‏ ‏الطَّائِفِ ‏ ‏قَالَ فَأَرْسَلَ إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَقِيلَ لَهُ إِنَّهُ لَا ‏ ‏يَهِيجُ ‏ ‏لِلرُّسُلِ قَالَ فَخَرَجْتُ مَعَهُمْ حَتَّى قَدِمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَلَمَّا رَآنِي قَالَ أَنْتَ ‏ ‏وَحْشِيٌّ ‏ ‏قَالَ قُلْتُ نَعَمْ قَالَ أَنْتَ قَتَلْتَ ‏ ‏حَمْزَةَ ‏ ‏قَالَ قُلْتُ قَدْ كَانَ مِنْ الْأَمْرِ مَا بَلَغَكَ يَا رَسُولَ اللَّهِ إِذْ قَالَ ‏ ‏مَا تَسْتَطِيعُ أَنْ تُغَيِّبَ عَنِّي وَجْهَكَ قَالَ فَرَجَعْتُ فَلَمَّا تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَرَجَ ‏ ‏مُسَيْلِمَةُ الْكَذَّابُ ‏ ‏قَالَ قُلْتُ لَأَخْرُجَنَّ إِلَى ‏ ‏مُسَيْلِمَةَ ‏ ‏لَعَلِّي أَقْتُلُهُ فَأُكَافِئَ بِهِ ‏ ‏حَمْزَةَ ‏ ‏قَالَ فَخَرَجْتُ مَعَ النَّاسِ فَكَانَ مِنْ أَمْرِهِمْ مَا كَانَ قَالَ فَإِذَا رَجُلٌ قَائِمٌ فِي ‏ ‏ثَلْمَةِ ‏ ‏جِدَارٍ كَأَنَّهُ جَمَلٌ ‏ ‏أَوْرَقُ ‏ ‏ثَائِرٌ ‏ ‏رَأْسُهُ قَالَ ‏ ‏فَأَرْمِيهِ بِحَرْبَتِي فَأَضَعُهَا بَيْنَ ثَدْيَيْهِ حَتَّى خَرَجَتْ مِنْ بَيْنِ كَتِفَيْهِ قَالَ وَوَثَبَ إِلَيْهِ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ فَضَرَبَهُ بِالسَّيْفِ عَلَى ‏ ‏هَامَتِهِ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الْفَضْلِ ‏ ‏فَأَخْبَرَنِي ‏ ‏سُلَيْمَانُ بْنُ يَسَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏فَقَالَتْ جَارِيَةٌ عَلَى ظَهْرِ بَيْتٍ وَأَمِيرُ الْمُؤْمِنِينَ قَتَلَهُ الْعَبْدُ الْأَسْوَدُ ‏","","",""],[15498,15498,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏وَحْشِيِّ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا نَأْكُلُ وَمَا نَشْبَعُ قَالَ فَلَعَلَّكُمْ تَأْكُلُونَ مُفْتَرِقِينَ ‏ ‏اجْتَمِعُوا عَلَى طَعَامِكُمْ وَاذْكُرُوا اسْمَ اللَّهِ تَعَالَى عَلَيْهِ يُبَارَكْ لَكُمْ فِيهِ ‏","","",""],[15499,15499,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ زُفَرَ ‏ ‏عَنْ ‏ ‏بَعْضِ بَنِي رَافِعِ بْنِ مَكِيثٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ مَكِيثٍ ‏ ‏وَكَانَ مِمَّنْ شَهِدَ ‏ ‏الْحُدَيْبِيَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حُسْنُ الْخُلُقِ نَمَاءٌ وَسُوءُ الْخُلُقِ شُؤْمٌ ‏ ‏وَالْبِرُّ ‏ ‏زِيَادَةٌ فِي الْعُمُرِ ‏ ‏وَالصَّدَقَةُ ‏ ‏تَمْنَعُ مِيتَةَ السَّوْءِ ‏","","",""],[15500,15500,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَنَّ ‏ ‏الْحُسَيْنَ بْنَ السَّائِبِ بْنِ أَبِي لُبَابَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏أَبَا لُبَابَةَ عَبْدَ الْمُنْذِرِ ‏ ‏لَمَّا تَابَ اللَّهُ عَلَيْهِ قَالَ يَا رَسُولَ اللَّهِ إِنَّ مِنْ تَوْبَتِي إِلَى اللَّهِ عَزَّ وَجَلَّ أَنْ أَهْجُرَ دَارَ قَوْمِي وَأُسَاكِنَكَ وَأَنْ ‏ ‏أَنْخَلِعَ ‏ ‏مِنْ مَالِي ‏ ‏صَدَقَةً ‏ ‏لِلَّهِ عَزَّ وَجَلَّ وَلِرَسُولِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُجْزِئُ عَنْكَ الثُّلُثُ ‏","","",""],[15501,15501,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَطَّافُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُجَمِّعُ بْنُ يَعْقُوبَ ‏ ‏عَنْ ‏ ‏غُلَامٍ ‏ ‏مِنْ أَهْلِ ‏ ‏قُباءٍ ‏ ‏أَنَّهُ أَدْرَكَهُ شَيْخًا ‏ ‏أَنَّهُ قَالَ ‏ ‏جَاءَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقُبَاءٍ ‏ ‏فَجَلَسَ فِي ‏ ‏فَيْءِ ‏ ‏الْأَحْمَرِ وَاجْتَمَعَ إِلَيْهِ نَاسٌ فَاسْتَسْقَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسُقِيَ ‏ ‏فَشَرِبَ وَأَنَا عَنْ يَمِينِهِ وَأَنَا أَحْدَثُ الْقَوْمِ فَنَاوَلَنِي فَشَرِبْتُ وَحَفِظْتُ أَنَّهُ صَلَّى بِنَا يَوْمَئِذٍ الصَّلَاةَ وَعَلَيْهِ نَعْلَاهُ لَمْ يَنْزِعْهُمَا ‏","","",""],[15502,15502,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ امْرَأَةِ عَبْدِ اللَّهِ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلنِّسَاءِ ‏ ‏تَصَدَّقْنَ ‏ ‏وَلَوْ مِنْ حُلِيِّكُنَّ قَالَتْ فَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏خَفِيفَ ذَاتِ الْيَدِ فَقَالَتْ لَهُ أَيَسَعُنِي أَنْ أَضَعَ ‏ ‏صَدَقَتِي ‏ ‏فِيكَ وَفِي بَنِي أَخِي ‏ ‏أَوْ بَنِي أَخٍ لِي ‏ ‏يَتَامَى فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏سَلِي عَنْ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا عَلَى بَابِهِ امْرَأَةٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يُقَالُ لَهَا ‏ ‏زَيْنَبُ ‏ ‏تَسْأَلُ عَمَّا أَسْأَلُ عَنْهُ فَخَرَجَ إِلَيْنَا ‏ ‏بِلَالٌ ‏ ‏فَقُلْنَا انْطَلِقْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلْهُ عَنْ ذَلِكَ وَلَا تُخْبِرْ مَنْ نَحْنُ فَانْطَلَقَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَنْ هُمَا فَقَالَ ‏ ‏زَيْنَبُ ‏ ‏فَقَالَ أَيُّ الزَّيَانِبِ فَقَالَ ‏ ‏زَيْنَبُ امْرَأَةُ عَبْدِ اللَّهِ ‏ ‏وَزَيْنَبُ الْأَنْصَارِيَّةُ ‏ ‏فَقَالَ نَعَمْ لَهُمَا أَجْرَانِ أَجْرُ الْقَرَابَةِ وَأَجْرُ ‏ ‏الصَّدَقَةِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ بْنِ الْمُصْطَلِقِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ امْرَأَةِ عَبْدِ اللَّهِ ‏ ‏قَالَتْ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالصَّدَقَةِ ‏ ‏فَقَالَ تَصَدَّقْنَ يَا مَعْشَرَ النِّسَاءِ فَذَكَرَ الْحَدِيثَ قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ بْنِ الْمُصْطَلِقِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَصَدَّقْنَ يَا مَعْشَرَ النِّسَاءِ فَذَكَرَهُ ‏","","",""],[15503,15503,"","","‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏وَسُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏رَائِطَةَ امْرَأَةِ عَبْدِ اللَّهِ ‏ ‏وَكَانَتْ امْرَأَةً صَنَاعًا وَكَانَتْ تَبِيعُ وَتَصَدَّقُ فَقَالَتْ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏يَوْمًا لَقَدْ شَغَلْتَنِي أَنْتَ وَوَلَدُكَ فَمَا أَسْتَطِيعُ أَنْ أَتَصَدَّقَ مَعَكُمْ فَقَالَ مَا أُحِبُّ إِنْ لَمْ يَكُنْ فِي ذَلِكَ أَجْرٌ أَنْ تَفْعَلِي فَسَأَلَا عَنْ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَكِ أَجْرُ مَا أَنْفَقْتِ عَلَيْهِمْ ‏","","",""],[15504,15504,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏رَائِطَةَ امْرَأَةِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏وَأُمِّ وَلَدِهِ وَكَانَتْ امْرَأَةً صَنَاعَ الْيَدِ قَالَ وَكَانَتْ تُنْفِقُ عَلَيْهِ وَعَلَى وَلَدِهِ مِنْ صَنْعَتِهَا قَالَتْ فَقُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏لَقَدْ شَغَلْتَنِي أَنْتَ وَوَلَدُكَ عَنْ ‏ ‏الصَّدَقَةِ ‏ ‏فَمَا أَسْتَطِيعُ أَنْ أَتَصَدَّقَ مَعَكُمْ بِشَيْءٍ فَقَالَ لَهَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَاللَّهِ مَا أُحِبُّ إِنْ لَمْ يَكُنْ فِي ذَلِكَ أَجْرٌ أَنْ تَفْعَلِي فَأَتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي امْرَأَةٌ ذَاتُ صَنْعَةٍ أَبِيعُ مِنْهَا وَلَيْسَ لِي وَلَا لِوَلَدِي وَلَا لِزَوْجِي نَفَقَةٌ غَيْرَهَا وَقَدْ شَغَلُونِي عَنْ ‏ ‏الصَّدَقَةِ ‏ ‏فَمَا أَسْتَطِيعُ أَنْ أَتَصَدَّقَ بِشَيْءٍ فَهَلْ لِي مِنْ أَجْرٍ فِيمَا أَنْفَقْتُ قَالَ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْفِقِي عَلَيْهِمْ فَإِنَّ لَكِ فِي ذَلِكَ أَجْرَ مَا أَنْفَقْتِ عَلَيْهِمْ ‏","","",""],[15505,15505,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَمْرِو بْنِ الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْمِي ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏مِنْ ‏ ‏بَطْنِ الْوَادِي ‏ ‏يَوْمَ النَّحْرِ ‏ ‏وَهُوَ يَقُولُ يَا أَيُّهَا النَّاسُ ‏ ‏لَا يَقْتُلُ بَعْضُكُمْ وَلَا يُصِيبُ بَعْضُكُمْ وَإِذَا رَمَيْتُمْ ‏ ‏الْجَمْرَةَ ‏ ‏فَارْمُوهَا بِمِثْلِ حَصَى الْخَذْفِ فَرَمَى بِسَبْعٍ وَلَمْ يَقِفْ وَخَلْفَهُ رَجُلٌ يَسْتُرُهُ قُلْتُ مَنْ هَذَا قَالُوا ‏ ‏الْفَضْلُ بْنُ الْعَبَّاسِ ‏","","",""],[15506,15506,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَمْرِو بْنِ الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏وَكَانَتْ بَايَعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ يَقُولُ وَهُوَ يَرْمِي الْجَمْرَةَ مِنْ ‏ ‏بَطْنِ الْوَادِي ‏ ‏وَهُوَ يَقُولُ يَا أَيُّهَا النَّاسُ ‏ ‏لَا يَقْتُلْ بَعْضُكُمْ بَعْضًا وَإِذَا رَأَيْتُمْ ‏ ‏الْجَمْرَةَ ‏ ‏فَارْمُوهَا بِمِثْلِ حَصَى الْخَذْفِ ‏","","",""],[15507,15507,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَمْرِو بْنِ الْأَحْوَصِ الْأَزْدِيِّ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا سَمِعَتْهُ يَقُولُ عِنْدَ ‏ ‏جَمْرَةِ الْعَقَبَةِ ‏ ‏يَا أَيُّهَا النَّاسُ ‏ ‏لَا تَقْتُلُوا أَنْفُسَكُمْ وَارْمُوا الْجَمْرَةَ ‏ ‏أَوْ الْجَمَرَاتِ ‏ ‏بِمِثْلِ حَصَى الْخَذْفِ ‏ ‏هَذَا آخِرُ مُسْنَدِ ‏ ‏الْمَكِّيِّينَ ‏","","",""],[15508,15508,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ إِلَى ‏ ‏سُتْرَةٍ ‏ ‏فَلْيَدْنُ مِنْهَا مَا لَا يَقْطَعُ الشَّيْطَانُ عَلَيْهِ صَلَاتَهُ ‏","","",""],[15509,15509,"","","‏ ‏قَالَ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏سَمِعَ ‏ ‏بُشَيْرَ بْنَ يَسَارٍ ‏ ‏مَوْلَى ‏ ‏بَنِي حَارِثَةَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏هَذَا حَدِيثُ ‏ ‏ابْنِ حَثْمَةَ ‏ ‏يُخْبِرُ عَنْ ‏ ‏سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏وَوُجِدَ ‏ ‏عَبْدُ اللَّهِ بْنُ سَهْلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَتِيلًا فِي ‏ ‏قَلِيبٍ ‏ ‏مِنْ ‏ ‏قُلُبِ ‏ ‏خَيْبَرَ ‏ ‏فَجَاءَ عَمَّاهُ وَأَخُوهُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخُوهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَهْلٍ ‏ ‏وَعَمَّاهُ ‏ ‏حُوَيِّصَةُ ‏ ‏وَمُحَيِّصَةُ ‏ ‏فَذَهَبَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏يَتَكَلَّمُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏الْكِبَرَ ‏ ‏الْكِبَرَ ‏ ‏فَتَكَلَّمَ أَحَدُ عَمَّيْهِ ‏ ‏إِمَّا ‏ ‏حُوَيِّصَةُ ‏ ‏وَإِمَّا ‏ ‏مُحَيِّصَةُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏نَسِيتُ أَيُّهُمَا الْكَبِيرُ مِنْهُمَا ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا وَجَدْنَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏قَتِيلًا فِي ‏ ‏قَلِيبٍ ‏ ‏مِنْ ‏ ‏قُلُبِ ‏ ‏خَيْبَرَ ‏ ‏ثُمَّ ذَكَرَ ‏ ‏يَهُودَ ‏ ‏وَشَرَّهُمْ وَعَدَاوَتَهُمْ قَالَ ‏ ‏لِيُقْسِمْ مِنْكُمْ خَمْسُونَ أَنَّ ‏ ‏يَهُودَ ‏ ‏قَتَلَتْهُ قَالُوا كَيْفَ نُقْسِمُ عَلَى مَا لَمْ نَرَ قَالَ فَتُبْرِئُكُمْ ‏ ‏يَهُودُ ‏ ‏بِخَمْسِينَ يَحْلِفُونَ أَنَّهُمْ لَمْ يَقْتُلُوهُ قَالُوا كَيْفَ ‏ ‏نَرْضَى بِأَيْمَانِهِمْ وَهُمْ مُشْرِكُونَ قَالَ ‏ ‏فَوَدَاهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ عِنْدِهِ ‏ ‏فَرَكَضَتْنِي ‏ ‏بَكْرَةٌ ‏ ‏مِنْهُ ‏ ‏قِيلَ ‏ ‏لِسُفْيَانَ ‏ ‏فِي الْحَدِيثِ وَتَسْتَحِقُّونَ دَمَ صَاحِبِكُمْ ‏ ‏قَالَ ‏ ‏هُوَ ذَا ‏","","",""],[15510,15510,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ التَّمْرِ بِالتَّمْرِ وَرَخَّصَ فِي ‏ ‏الْعَرَايَا ‏ ‏أَنْ ‏ ‏تُشْتَرَى ‏ ‏بِخَرْصِهَا ‏ ‏يَأْكُلُهَا أَهْلُهَا رُطَبًا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏قَالَ لِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَمَا عِلْمُ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏بِالْعَرَايَا ‏ ‏قُلْتُ أَخْبَرَهُمْ ‏ ‏عَطَاءٌ ‏ ‏سَمِعَهُ مِنْ ‏ ‏جَابِرٍ ‏","","",""],[15511,15511,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خُبَيْبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَسْعُودِ بْنِ نِيَارٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏قَالَ ‏ ‏أَتَانَا وَنَحْنُ فِي مَسْجِدِنَا قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏خَرَصْتُمْ ‏ ‏فَخُذُوا ‏ ‏وَدَعُوا دَعُوا الثُّلُثَ فَإِنْ لَمْ تَدَعُوا ‏ ‏أَوْ تَجُدُّوا ‏ ‏شُعْبَةُ ‏ ‏الشَّاكُّ ‏ ‏الثُّلُثَ فَالرُّبُعَ ‏","","",""],[15512,15512,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏خُبَيْبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَسْعُودِ بْنِ نِيَارٍ ‏ ‏قَالَ ‏ ‏أَتَانَا ‏ ‏سَهْلُ بْنُ أَبِي حَثْمَةَ ‏ ‏فِي مَسْجِدِنَا فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏خَرَصْتُمْ ‏ ‏فَخُذُوا وَدَعُوا دَعُوا الثُّلُثَ فَإِنْ لَمْ تَجُدُّوا ‏ ‏أَوْ تَدَعُوا ‏ ‏فَالرُّبُعَ ‏","","",""],[15513,15513,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْقُدُّوسِ بْنُ بَكْرِ بْنِ خُنَيْسٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَالْحَجَّاجِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سُلَيْمَانَ بْنِ أَبِي حَثْمَةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏حَبِيبَةُ ابْنَةُ سَهْلٍ ‏ ‏تَحْتَ ‏ ‏ثَابِتِ بْنِ قَيْسِ بْنِ شَمَّاسٍ الْأَنْصَارِيِّ ‏ ‏فَكَرِهَتْهُ وَكَانَ رَجُلًا دَمِيمًا فَجَاءَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي لَأَرَاهُ فَلَوْلَا مَخَافَةُ اللَّهِ عَزَّ وَجَلَّ لَبَزَقْتُ فِي وَجْهِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَرُدِّينَ عَلَيْهِ حَدِيقَتَهُ الَّتِي ‏ ‏أَصْدَقَكِ ‏ ‏قَالَتْ نَعَمْ فَأَرْسَلَ إِلَيْهِ فَرَدَّتْ عَلَيْهِ حَدِيقَتَهُ وَفَرَّقَ بَيْنَهُمَا قَالَ فَكَانَ ذَلِكَ أَوَّلَ ‏ ‏خُلْعٍ ‏ ‏كَانَ فِي الْإِسْلَامِ ‏","","",""],[15514,15514,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏بُشَيْرُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ ‏ ‏عَبْدُ اللَّهِ بْنُ سَهْلٍ ‏ ‏أَخُو ‏ ‏بَنِي حَارِثَةَ ‏ ‏يَعْنِي فِي نَفَرٍ مِنْ ‏ ‏بَنِي حَارِثَةَ ‏ ‏إِلَى ‏ ‏خَيْبَرَ ‏ ‏يَمْتَارُونَ مِنْهَا تَمْرًا قَالَ فَعُدِيَ عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ سَهْلٍ ‏ ‏فَكُسِرَتْ عُنُقُهُ ثُمَّ طُرِحَ فِي مَنْهَرٍ مِنْ مَنَاهِرِ عُيُونِ ‏ ‏خَيْبَرَ ‏ ‏وَفَقَدَهُ أَصْحَابُهُ فَالْتَمَسُوهُ حَتَّى وَجَدُوهُ ‏ ‏فَغَيَّبُوهُ ‏ ‏قَالَ ثُمَّ قَدِمُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَقْبَلَ أَخُوهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَهْلٍ ‏ ‏وَابْنَا عَمِّهِ ‏ ‏حُوَيِّصَةُ ‏ ‏وَمُحَيِّصَةُ ‏ ‏وَهُمَا كَانَا ‏ ‏أَسَنَّ ‏ ‏مِنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏وَكَانَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏إِذًا أَقْدَمَ الْقَوْمِ وَصَاحِبَ الدَّمِ فَتَقَدَّمَ لِذَلِكَ فَكَلَّمَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ ابْنَيْ عَمِّهِ ‏ ‏حُوَيِّصَةَ ‏ ‏وَمُحَيِّصَةَ ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكِبَرَ ‏ ‏الْكِبَرَ ‏ ‏فَاسْتَأْخَرَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَتَكَلَّمَ ‏ ‏حُوَيِّصَةُ ‏ ‏ثُمَّ تَكَلَّمَ ‏ ‏مُحَيِّصَةُ ‏ ‏ثُمَّ تَكَلَّمَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ عُدِيَ عَلَى صَاحِبِنَا فَقُتِلَ وَلَيْسَ ‏ ‏بِخَيْبَرَ ‏ ‏عَدُوٌّ إِلَّا ‏ ‏يَهُودَ ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُسَمُّونَ قَاتِلَكُمْ ثُمَّ تَحْلِفُونَ عَلَيْهِ خَمْسِينَ يَمِينًا ثُمَّ تُسْلِمُهُ قَالَ فَقَالُوا يَا رَسُولَ اللَّهِ مَا كُنَّا لِنَحْلِفَ عَلَى مَا لَمْ نَشْهَدْ قَالَ فَيَحْلِفُونَ لَكُمْ خَمْسِينَ يَمِينًا وَيَبْرَءُونَ مِنْ دَمِ صَاحِبِكُمْ قَالُوا يَا رَسُولَ اللَّهِ مَا كُنَّا لِنَقْبَلَ أَيْمَانَ ‏ ‏يَهُودَ ‏ ‏مَا هُمْ فِيهِ مِنْ الْكُفْرِ أَعْظَمُ مِنْ أَنْ يَحْلِفُوا عَلَى إِثْمٍ قَالَ ‏ ‏فَوَدَاهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ عِنْدِهِ مِائَةَ نَاقَةٍ ‏ ‏قَالَ ‏ ‏يَقُولُ ‏ ‏سَهْلٌ ‏ ‏فَوَاللَّهِ مَا أَنْسَى ‏ ‏بَكْرَةً ‏ ‏مِنْهَا حَمْرَاءَ ‏ ‏رَكَضَتْنِي ‏ ‏وَأَنَا أَحُوزُهَا ‏","","",""],[15515,15515,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏أَبِي لَيْلَى بْنِ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏أَنَّ ‏ ‏سَهْلَ بْنَ أَبِي حَثْمَةَ ‏ ‏أَخْبَرَهُ ‏ ‏وَرِجَالٌ مِنْ كُبَرَاءِ قَوْمِهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِحُوَيِّصَةَ ‏ ‏وَمُحَيِّصَةَ ‏ ‏وَعَبْدِ الرَّحْمَنِ ‏ ‏أَتَحْلِفُونَ وَتَسْتَحِقُّونَ دَمَ صَاحِبِكُمْ قَالُوا لَا قَالَ فَتَحْلِفُ ‏ ‏يَهُودُ ‏ ‏قَالُوا لَيْسُوا بِمُسْلِمِينَ ‏ ‏فَوَدَاهُ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ عِنْدِهِ ‏","","",""],[15516,15516,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ يَعْنِي أَبَا مَسْلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَسِيدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَجُلًا قَالَ ‏ ‏لِابْنِ الزُّبَيْرِ ‏ ‏أَفْتِنَا فِي ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْهُ ‏","","",""],[15517,15517,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْقُدُّوسِ بْنُ بَكْرِ بْنِ خُنَيْسٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏افْتَتَحَ الصَّلَاةَ فَرَفَعَ يَدَيْهِ حَتَّى جَاوَزَ بِهِمَا أُذُنَيْهِ ‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏وَأَنَا شَاهِدٌ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عَجْلَانَ ‏ ‏وَزِيَادَ بْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو ‏ ‏هَكَذَا وَعَقَدَ ‏ ‏ابْنُ الزُّبَيْرِ ‏","","",""],[15518,15518,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَامِرُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَلَسَ فِي التَّشَهُّدِ وَضَعَ يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى وَيَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى وَأَشَارَ بِالسَّبَّابَةِ وَلَمْ يُجَاوِزْ بَصَرُهُ إِشَارَتَهُ ‏","","",""],[15519,15519,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَجُلًا حَلَفَ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ كَاذِبًا فَغَفَرَ اللَّهُ لَهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏مِنْ قَبْلِ التَّوْحِيدِ ‏","","",""],[15520,15520,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ ‏ ‏عَنِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِرَجُلٍ ‏ ‏أَنْتَ أَكْبَرُ وَلَدِ أَبِيكَ فَاحْجُجْ عَنْهُ ‏","","",""],[15521,15521,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي إِسْحَاقُ بْنُ يَسَارٍ ‏ ‏قَالَ ‏ ‏إِنَّا ‏ ‏لَبِمَكَّةَ ‏ ‏إِذْ خَرَجَ عَلَيْنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏فَنَهَى عَنْ ‏ ‏التَّمَتُّعِ ‏ ‏بِالْعُمْرَةِ إِلَى الْحَجِّ وَأَنْكَرَ أَنْ يَكُونَ النَّاسُ صَنَعُوا ذَلِكَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَلَغَ ذَلِكَ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏فَقَالَ وَمَا عِلْمُ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏بِهَذَا فَلْيَرْجِعْ إِلَى أُمِّهِ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ‏ ‏فَلْيَسْأَلْهَا فَإِنْ لَمْ يَكُنْ ‏ ‏الزُّبَيْرُ ‏ ‏قَدْ رَجَعَ إِلَيْهَا حَلَالًا وَحَلَّتْ فَبَلَغَ ذَلِكَ ‏ ‏أَسْمَاءَ ‏ ‏فَقَالَتْ يَغْفِرُ اللَّهُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏وَاللَّهِ لَقَدْ أَفْحَشَ قَدْ وَاللَّهِ صَدَقَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَقَدْ حَلُّوا وَأَحْلَلْنَا وَأَصَابُوا النِّسَاءَ ‏","","",""],[15522,15522,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُصْعَبُ بْنُ ثَابِتٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏كَانَتْ بَيْنَهُ وَبَيْنَ أَخِيهِ ‏ ‏عَمْرِو بْنِ الزُّبَيْرِ ‏ ‏خُصُومَةٌ فَدَخَلَ ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏عَلَى ‏ ‏سَعِيدِ بْنِ الْعَاصِ ‏ ‏وَعَمْرُو بْنُ الزُّبَيْرِ ‏ ‏مَعَهُ عَلَى السَّرِيرِ فَقَالَ ‏ ‏سَعِيدٌ ‏ ‏لِعَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏هَاهُنَا فَقَالَ لَا ‏ ‏قَضَاءُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ سُنَّةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ الْخَصْمَيْنِ يَقْعُدَانِ بَيْنَ يَدَيْ الْحَكَمِ ‏","","",""],[15523,15523,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏يَقُولُ فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ حِينَ يُسَلِّمُ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ لَا إِلَهَ إِلَّا اللَّهُ وَلَا نَعْبُدُ إِلَّا إِيَّاهُ وَلَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهَلِّلُ ‏ ‏بِهِنَّ ‏ ‏دُبُرَ ‏ ‏كُلِّ صَلَاةٍ ‏","","",""],[15524,15524,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ يَعْنِي ابْنَ عُمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏فَقَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏فَمَا كَانَ ‏ ‏عُمَرُ ‏ ‏يَسْمَعُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ هَذِهِ الْآيَةِ حَتَّى يَسْتَفْهِمَهُ ‏ ‏يَعْنِي قَوْلَهُ تَعَالَى ‏ { ‏لَا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ ‏}","","",""],[15525,15525,"","","‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرُ بْنُ سُلَيْمَانَ الرَّقِّيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏فُرَاتِ بْنِ عَبْدِ اللَّهِ وَهُوَ فُرَاتٌ الْقَزَّازُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏وَكَانَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏جَعَلَهُ عَلَى الْقَضَاءِ إِذْ جَاءَهُ كِتَابُ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏سَلَامٌ عَلَيْكَ أَمَّا بَعْدُ فَإِنَّكَ كَتَبْتَ تَسْأَلُنِي عَنْ الْجَدِّ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ كُنْتُ مُتَّخِذًا مِنْ هَذِهِ الْأُمَّةِ خَلِيلًا دُونَ رَبِّي عَزَّ وَجَلَّ لَاتَّخَذْتُ ‏ ‏ابْنَ أَبِي قُحَافَةَ ‏ ‏وَلَكِنَّهُ أَخِي فِي الدِّينِ وَصَاحِبِي فِي الْغَارِ جَعَلَ الْجَدَّ أَبًا وَأَحَقُّ مَا أَخَذْنَاهُ قَوْلُ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[15526,15526,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ فَحَدَّثَنِي ‏ ‏وَهْبُ بْنُ كَيْسَانَ ‏ ‏مَوْلَى ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏فِي يَوْمِ الْعِيدِ يَقُولُ حِينَ ‏ ‏صَلَّى قَبْلَ الْخُطْبَةِ ثُمَّ قَامَ يَخْطُبُ النَّاسَ يَا أَيُّهَا النَّاسُ ‏ ‏كَذَا ‏ ‏سُنَّةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15527,15527,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الْمَوَالِي ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نَافِعُ بْنُ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى الْعِشَاءَ رَكَعَ أَرْبَعَ رَكَعَاتٍ وَأَوْتَرَ بِسَجْدَةٍ ثُمَّ نَامَ حَتَّى يُصَلِّيَ بَعْدَ صَلَاتِهِ بِاللَّيْلِ ‏","","",""],[15528,15528,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُحَرِّمُ مِنْ الرَّضَاعِ الْمَصَّةُ وَالْمَصَّتَانِ ‏","","",""],[15529,15529,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ ثَابِتٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَامِرُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَدِمَتْ ‏ ‏قُتَيْلَةُ ابْنَةُ عَبْدِ الْعُزَّى بْنِ عَبْدِ أَسْعَدَ ‏ ‏مِنْ ‏ ‏بَنِي مَالِكِ بْنِ حَسَلٍ ‏ ‏عَلَى ابْنَتِهَا ‏ ‏أَسْمَاءَ ابْنَةِ أَبِي بَكْرٍ ‏ ‏بِهَدَايَا ضِبَابٍ ‏ ‏وَأَقِطٍ ‏ ‏وَسَمْنٍ وَهِيَ مُشْرِكَةٌ ‏ ‏فَأَبَتْ ‏ ‏أَسْمَاءُ ‏ ‏أَنْ تَقْبَلَ هَدِيَّتَهَا وَتُدْخِلَهَا بَيْتَهَا فَسَأَلَتْ ‏ ‏عَائِشَةُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏لَا يَنْهَاكُمْ اللَّهُ عَنْ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ ‏} ‏إِلَى آخِرِ الْآيَةِ فَأَمَرَهَا أَنْ تَقْبَلَ هَدِيَّتَهَا وَأَنْ تُدْخِلَهَا بَيْتَهَا ‏","","",""],[15530,15530,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏إِنَّ الَّذِي قَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كُنْتُ مُتَّخِذًا خَلِيلًا سِوَى اللَّهِ عَزَّ وَجَلَّ حَتَّى أَلْقَاهُ لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏جَعَلَ الْجَدَّ أَبًا ‏","","",""],[15531,15531,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ نَبِيٍّ ‏ ‏حَوَارِيٌّ ‏ ‏وَحَوَارِيَّ ‏ ‏الزُّبَيْرُ ‏ ‏وَابْنُ عَمَّتِي ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏مُرْسَلٌ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏مُرْسَلٌ لَيْسَ فِيهِ ‏ ‏ابْنُ الزُّبَيْرِ ‏","","",""],[15532,15532,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏خَاصَمَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏الزُّبَيْرَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏شِرَاجِ الْحَرَّةِ ‏ ‏الَّتِي يَسْقُونَ بِهَا النَّخْلَ فَقَالَ الْأَنْصَارِيُّ ‏ ‏لِلزُّبَيْرِ ‏ ‏سَرِّحْ ‏ ‏الْمَاءَ فَأَبَى فَكَلَّمَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْقِ يَا ‏ ‏زُبَيْرُ ‏ ‏ثُمَّ أَرْسِلْ إِلَى جَارِكَ فَغَضِبَ الْأَنْصَارِيُّ فَقَالَ يَا رَسُولَ اللَّهِ أَنْ كَانَ ابْنَ عَمَّتِكَ ‏ ‏فَتَلَوَّنَ ‏ ‏وَجْهُهُ ثُمَّ قَالَ احْبِسْ الْمَاءَ حَتَّى يَبْلُغَ إِلَى ‏ ‏الْجُدُرِ ‏ ‏قَالَ ‏ ‏الزُّبَيْرُ ‏ ‏وَاللَّهِ إِنِّي لَأَحْسِبُ هَذِهِ الْآيَةَ نَزَلَتْ فِي ذَلِكَ ‏ { ‏فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ‏ ‏إِلَى قَوْلِهِ ‏ ‏وَيُسَلِّمُوا تَسْلِيمًا ‏}","","",""],[15533,15533,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَبِيبٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏ ‏وَصَلَاةٌ فِي ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏أَفْضَلُ مِنْ مِائَةِ صَلَاةٍ فِي هَذَا ‏","","",""],[15534,15534,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ الْبُنَانِيُّ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏يَخْطُبُنَا ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏وَهُوَ يَخْطُبُ ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا لَمْ يَلْبَسْهُ فِي الْآخِرَةِ ‏","","",""],[15535,15535,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثُوَيْرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏يَقُولُ ‏ ‏هَذَا ‏ ‏يَوْمُ عَاشُورَاءَ ‏ ‏فَصُومُوا فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ صُومُوهُ ‏","","",""],[15536,15536,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏إِنَّ الَّذِي قَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كُنْتُ مُتَّخِذًا خَلِيلًا سِوَى اللَّهِ حَتَّى أَلْقَاهُ لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏جَعَلَ الْجَدَّ أَبًا ‏","","",""],[15537,15537,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُحَرِّمُ الْمَصَّةُ وَالْمَصَّتَانِ ‏","","",""],[15538,15538,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ أَبِي عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏يَخْطُبُ ‏ ‏عَلَى هَذَا الْمِنْبَرِ وَهُوَ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَلَّمَ فِي ‏ ‏دُبُرِ ‏ ‏الصَّلَاةِ ‏ ‏أَوْ الصَّلَوَاتِ ‏ ‏يَقُولُ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ وَلَا نَعْبُدُ إِلَّا إِيَّاهُ أَهْلُ النِّعْمَةِ وَالْفَضْلِ وَالثَّنَاءِ الْحَسَنِ لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ ‏","","",""],[15539,15539,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏ذَكَرَ ‏ ‏ابْنَةَ أَبِي جَهْلٍ ‏ ‏فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّمَا ‏ ‏فَاطِمَةُ ‏ ‏بِضْعَةٌ ‏ ‏مِنِّي يُؤْذِينِي مَا آذَاهَا ‏ ‏وَيُنْصِبُنِي مَا أَنْصَبَهَا ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْحَكَمِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏","","",""],[15540,15540,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ مِنْ ‏ ‏خَثْعَمٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ أَبِي أَدْرَكَهُ الْإِسْلَامُ وَهُوَ شَيْخٌ كَبِيرٌ لَا يَسْتَطِيعُ رُكُوبَ الرَّحْلِ وَالْحَجُّ مَكْتُوبٌ عَلَيْهِ أَفَأَحُجُّ عَنْهُ قَالَ أَنْتَ أَكْبَرُ وَلَدِهِ قَالَ نَعَمْ قَالَ أَرَأَيْتَ لَوْ كَانَ عَلَى أَبِيكَ دَيْنٌ فَقَضَيْتَهُ عَنْهُ أَكَانَ ذَلِكَ يُجْزِئُ عَنْهُ قَالَ نَعَمْ قَالَ فَاحْجُجْ عَنْهُ ‏","","",""],[15541,15541,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَّتَ لِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنًا ‏","","",""],[15542,15542,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏زَمْعَةَ ‏ ‏كَانَتْ لَهُ جَارِيَةٌ ‏ ‏فَكَانَ ‏ ‏يَطَؤُهَا ‏ ‏وَكَانُوا يَتَّهِمُونَهَا فَوَلَدَتْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِسَوْدَةَ ‏ ‏أَمَّا الْمِيرَاثُ فَلَهُ وَأَمَّا أَنْتِ فَاحْتَجِبِي مِنْهُ يَا ‏ ‏سَوْدَةُ ‏ ‏فَإِنَّهُ لَيْسَ لَكِ بِأَخٍ ‏","","",""],[15543,15543,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏وَهُوَ مُسْتَنِدٌ إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏وَهُوَ يَقُولُ وَرَبِّ هَذِهِ ‏ ‏الْكَعْبَةِ ‏ ‏لَقَدْ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فُلَانًا وَمَا وُلِدَ مِنْ صُلْبِهِ ‏","","",""],[15544,15544,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏لِعَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏أَتَذْكُرُ يَوْمَ ‏ ‏اسْتَقْبَلْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَمَلَنِي وَتَرَكَكَ وَكَانَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسْتَقْبَلُ بِالصِّبْيَانِ إِذَا جَاءَ مِنْ سَفَرٍ ‏","","",""],[15545,15545,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ الْأَسْوَدِ الْقُرَشِيُّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَعْلِنُوا النِّكَاحَ ‏","","",""],[15546,15546,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏أَبِي مَسْلَمَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ الْعَزِيزِ بْنَ أَسِيدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏وَسَأَلَهُ رَجُلٌ عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏","","",""],[15547,15547,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏ثُوَيْرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏وَهُوَ عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏هَذَا ‏ ‏يَوْمُ عَاشُورَاءَ ‏ ‏فَصُومُوا فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِصَوْمِهِ ‏","","",""],[15548,15548,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعُ بْنُ عُمَرَ الْجُمَحِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ ‏ ‏كَادَ الْخَيِّرَانِ أَنْ يَهْلِكَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏لَمَّا قَدِمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفْدُ ‏ ‏بَنِي تَمِيمٍ ‏ ‏أَشَارَ أَحَدُهُمَا ‏ ‏بِالْأَقْرَعِ بْنِ حَابِسٍ الْحَنْظَلِيِّ ‏ ‏أَخِي ‏ ‏بَنِي مُجَاشِعٍ ‏ ‏وَأَشَارَ الْآخَرُ بِغَيْرِهِ قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏لِعُمَرَ ‏ ‏إِنَّمَا أَرَدْتَ خِلَافِي فَقَالَ ‏ ‏عُمَرُ ‏ ‏مَا أَرَدْتُ خِلَافَكَ فَارْتَفَعَتْ أَصْوَاتُهُمَا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَزَلَتْ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ ‏ ‏إِلَى قَوْلِهِ ‏ ‏عَظِيمٌ ‏} ‏قَالَ ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏قَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏فَكَانَ ‏ ‏عُمَرُ ‏ ‏بَعْدَ ذَلِكَ وَلَمْ يَذْكُرْ ذَلِكَ عَنْ أَبِيهِ ‏ ‏يَعْنِي ‏ ‏أَبَا بَكْرٍ ‏ ‏إِذَا حَدَّثَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَهُ كَأَخِي السِّرَارِ لَمْ يَسْمَعْهُ حَتَّى يَسْتَفْهِمَهُ ‏","","",""],[15549,15549,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ أَبِي رَاشِدٍ ‏ ‏وَعَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي غَرَزَةَ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُسَمَّى ‏ ‏السَّمَاسِرَةَ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَانَا ‏ ‏بِالْبَقِيعِ ‏ ‏فَقَالَ يَا مَعْشَرَ التُّجَّارِ فَسَمَّانَا بِاسْمٍ أَحْسَنَ مِنْ اسْمِنَا ‏ ‏إِنَّ الْبَيْعَ يَحْضُرُهُ الْحَلِفُ وَالْكَذِبُ ‏ ‏فَشُوبُوهُ ‏ ‏بِالصَّدَقَةِ ‏","","",""],[15550,15550,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي غَرَزَةَ ‏ ‏قَالَ ‏ ‏كُنَّا نَبْتَاعُ ‏ ‏الْأَوْسَاقَ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَكُنَّا ‏ ‏نُسَمَّى ‏ ‏السَّمَاسِرَةَ ‏ ‏قَالَ فَأَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمَّانَا بِاسْمٍ هُوَ أَحْسَنُ مِمَّا كُنَّا ‏ ‏نُسَمِّي بِهِ أَنْفُسَنَا فَقَالَ يَا مَعْشَرَ التُّجَّارِ إِنَّ هَذَا الْبَيْعَ يَحْضُرُهُ ‏ ‏اللَّغْوُ ‏ ‏وَالْحَلِفُ ‏ ‏فَشُوبُوهُ ‏ ‏بِالصَّدَقَةِ ‏","","",""],[15551,15551,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي غَرَزَةَ ‏ ‏قَالَ ‏ ‏أَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ فِي السُّوقِ فَقَالَ ‏ ‏إِنَّ هَذِهِ السُّوقَ يُخَالِطُهَا ‏ ‏اللَّغْوُ ‏ ‏وَحَلِفٌ ‏ ‏فَشُوبُوهَا ‏ ‏بِصَدَقَةٍ ‏","","",""],[15552,15552,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏قَيْسِ بْنِ أَبِي غَرَزَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ إِلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ نَبِيعُ ‏ ‏الرَّقِيقَ ‏ ‏نُسَمَّى ‏ ‏السَّمَاسِرَةَ ‏ ‏فَقَالَ يَا مَعْشَرَ التُّجَّارِ ‏ ‏إِنَّ بَيْعَكُمْ هَذَا يُخَالِطُهُ ‏ ‏لَغْوٌ ‏ ‏وَحَلِفٌ ‏ ‏فَشُوبُوهُ ‏ ‏بِصَدَقَةٍ ‏ ‏أَوْ بِشَيْءٍ مِنْ ‏ ‏صَدَقَةٍ ‏","","",""],[15553,15553,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي غَرَزَةَ ‏ ‏قَالَ ‏ ‏كُنَّا نَبِيعُ ‏ ‏الرَّقِيقَ ‏ ‏فِي السُّوقِ وَكُنَّا ‏ ‏نُسَمَّى ‏ ‏السَّمَاسِرَةَ ‏ ‏فَسَمَّانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَحْسَنَ مِمَّا سَمَّيْنَا بِهِ أَنْفُسَنَا فَقَالَ يَا مَعْشَرَ التُّجَّارِ إِنَّ هَذَا الْبَيْعَ يَحْضُرُهُ ‏ ‏اللَّغْوُ ‏ ‏وَالْأَيْمَانُ ‏ ‏فَشُوبُوهُ ‏ ‏بِالصَّدَقَةِ ‏","","",""],[15554,15554,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي غَرَزَةَ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُسَمَّى عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّمَاسِرَةَ ‏ ‏فَمَرَّ بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمَّانَا بِاسْمٍ هُوَ أَحْسَنُ مِنْهُ فَقَالَ يَا مَعْشَرَ التُّجَّارِ إِنَّ هَذَا الْبَيْعَ يَحْضُرُهُ ‏ ‏اللَّغْوُ ‏ ‏وَالْحَلِفُ ‏ ‏فَشُوبُوهُ ‏ ‏بِالصَّدَقَةِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْعَوَّامُ بْنُ حَوْشَبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ ‏ ‏مَوْلَى ‏ ‏صُخَيْرٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَنْهَى عَنْ بَيْعٍ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّهَا مَعَايِشُنَا قَالَ فَقَالَ لَا ‏ ‏خِلَابَ ‏ ‏إِذًا وَكُنَّا ‏ ‏نُسَمَّى ‏ ‏السَّمَاسِرَةَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[15555,15555,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏فُرَاتٍ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ بْنِ أَسِيدٍ ‏ ‏اطَّلَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْنَا وَنَحْنُ نَتَذَاكَرُ السَّاعَةَ فَقَالَ مَا تَذْكُرُونَ قَالُوا نَذْكُرُ السَّاعَةَ فَقَالَ ‏ ‏إِنَّهَا لَنْ تَقُومَ حَتَّى تَرَوْنَ عَشْرَ آيَاتٍ الدُّخَانُ ‏ ‏وَالدَّجَّالُ ‏ ‏وَالدَّابَّةُ وَطُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا وَنُزُولُ ‏ ‏عِيسَى ابْنِ مَرْيَمَ ‏ ‏وَيَأْجُوجُ ‏ ‏وَمَأْجُوجُ ‏ ‏وَثَلَاثُ خُسُوفٍ خَسْفٌ بِالْمَشْرِقِ وَخَسْفٌ بِالْمَغْرِبِ وَخَسْفٌ ‏ ‏بِجَزِيرَةِ الْعَرَبِ ‏ ‏وَآخِرُ ذَلِكَ نَارٌ تَخْرُجُ مِنْ قِبَلِ تَطْرُدُ النَّاسَ إِلَى مَحْشَرِهِمْ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏سَقَطَ كَلِمَةٌ ‏","","",""],[15556,15556,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ بْنِ أَسِيدٍ الْغِفَارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ الْمَلَكُ عَلَى ‏ ‏النُّطْفَةِ ‏ ‏بَعْدَمَا تَسْتَقِرُّ فِي الرَّحِمِ بِأَرْبَعِينَ لَيْلَةً ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً أَوْ خَمْسِينَ وَأَرْبَعِينَ لَيْلَةً ‏ ‏فَيَقُولُ يَا رَبِّ مَاذَا أَشَقِيٌّ أَمْ سَعِيدٌ أَذَكَرٌ أَمْ أُنْثَى فَيَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى فَيَكْتُبَانِ فَيَقُولَانِ مَاذَا أَذَكَرٌ أَمْ أُنْثَى فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ فَيَكْتُبَانِ فَيُكْتَبُ عَمَلُهُ وَأَثَرُهُ وَمُصِيبَتُهُ وَرِزْقُهُ ثُمَّ تُطْوَى الصَّحِيفَةُ فَلَا يُزَادُ عَلَى مَا فِيهَا وَلَا يُنْقَصُ ‏","","",""],[15557,15557,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏فُرَاتٍ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏أَبِي سَرِيحَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غُرْفَةٍ وَنَحْنُ تَحْتَهَا نَتَحَدَّثُ قَالَ فَأَشْرَفَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا تَذْكُرُونَ قَالُوا السَّاعَةَ قَالَ ‏ ‏إِنَّ السَّاعَةَ لَنْ تَقُومَ حَتَّى تَرَوْنَ عَشْرَ آيَاتٍ خَسْفٌ بِالْمَشْرِقِ وَخَسْفٌ بِالْمَغْرِبِ وَخَسْفٌ فِي ‏ ‏جَزِيرَةِ الْعَرَبِ ‏ ‏وَالدُّخَانُ ‏ ‏وَالدَّجَّالُ ‏ ‏وَالدَّابَّةُ وَطُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا ‏ ‏وَيَأْجُوجُ ‏ ‏وَمَأْجُوجُ ‏ ‏وَنَارٌ تَخْرُجُ مِنْ ‏ ‏قَعْرِ ‏ ‏عَدَنٍ ‏ ‏تُرَحِّلُ النَّاسَ ‏ ‏فَقَالَ ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُهُ وَأَحْسِبُهُ قَالَ تَنْزِلُ مَعَهُمْ حَيْثُ نَزَلُوا ‏ ‏وَتَقِيلُ ‏ ‏مَعَهُمْ حَيْثُ قَالُوا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَحَدَّثَنِي ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏رَجُلٌ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏أَبِي سَرِيحَةَ ‏ ‏لَمْ يَرْفَعْهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَحَدُ هَذَيْنِ الرَّجُلَيْنِ نُزُولُ ‏ ‏عِيسَى ابْنِ مَرْيَمَ ‏ ‏وَقَالَ الْآخَرُ رِيحٌ ‏ ‏تُلْقِيهِمْ فِي الْبَحْرِ ‏","","",""],[15558,15558,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏فُرَاتٍ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ بْنِ أَسِيدٍ الْغِفَارِيِّ ‏ ‏قَالَ ‏ ‏أَشْرَفَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ غُرْفَةٍ وَنَحْنُ نَتَذَاكَرُ السَّاعَةَ فَقَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَرَوْنَ عَشْرَ آيَاتٍ طُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا وَالدُّخَانُ وَالدَّابَّةُ وَخُرُوجُ ‏ ‏يَأْجُوجَ ‏ ‏وَمَأْجُوجَ ‏ ‏وَخُرُوجُ ‏ ‏عِيسَى ابْنِ مَرْيَمَ ‏ ‏وَالدَّجَّالِ ‏ ‏وَثَلَاثُ خُسُوفٍ خَسْفٌ بِالْمَغْرِبِ وَخَسْفٌ بِالْمَشْرِقِ وَخَسْفٌ ‏ ‏بِجَزِيرَةِ الْعَرَبِ ‏ ‏وَنَارٌ تَخْرُجُ مِنْ ‏ ‏قَعْرِ ‏ ‏عَدَنٍ ‏ ‏تَسُوقُ ‏ ‏أَوْ تَحْشُرُ ‏ ‏النَّاسَ تَبِيتُ مَعَهُمْ حَيْثُ بَاتُوا ‏ ‏وَتَقِيلُ ‏ ‏مَعَهُمْ حَيْثُ ‏ ‏قَالُوا ‏","","",""],[15559,15559,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ بْنِ أَسِيدٍ الْغِفَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَ بِمَوْتِ ‏ ‏النَّجَاشِيِّ ‏ ‏قَالَ فَقَالَ ‏ ‏صَلُّوا عَلَى أَخٍ لَكُمْ بِغَيْرِ بِلَادِكُمْ ‏","","",""],[15560,15560,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَأَزْهَرُ بْنُ الْقَاسِمِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ بْنِ أَسِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ عَلَيْهِمْ يَوْمًا فَقَالَ ‏ ‏صَلُّوا عَلَى صَاحِبِكُمْ مَاتَ بِغَيْرِ بِلَادِكُمْ قَالُوا مَنْ هُوَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏صُحْمَةُ النَّجَاشِيُّ ‏ ‏وَقَالَ ‏ ‏أَزْهَرُ ‏ ‏صَحْمَةُ ‏ ‏وَقَالَ ‏ ‏أَزْهَرُ ‏ ‏أَبِي الطُّفَيْلِ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ بْنِ أَسِيدٍ الْغِفَارِيِّ ‏","","",""],[15561,15561,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُثَنَّى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ بْنِ أَسِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ ذَاتَ يَوْمٍ فَقَالَ ‏ ‏صَلُّوا عَلَى أَخٍ لَكُمْ مَاتَ بِغَيْرِ أَرْضِكُمْ قَالُوا مَنْ هُوَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏صُحْمَةُ النَّجَاشِيُّ ‏ ‏فَقَامُوا فَصَلَّوْا عَلَيْهِ ‏","","",""],[15562,15562,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُبَيْدُ بْنُ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏وَقَدْ سَمِعْتُهُ مِنْ ‏ ‏عُقْبَةَ ‏ ‏وَلَكِنِّي لِحَدِيثِ ‏ ‏عُبَيْدٍ ‏ ‏أَحْفَظُ ‏ ‏قَالَ ‏ ‏تَزَوَّجْتُ فَجَاءَتْنَا امْرَأَةٌ سَوْدَاءُ فَقَالَتْ إِنِّي قَدْ أَرْضَعْتُكُمَا فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ ‏ ‏إِنِّي تَزَوَّجْتُ امْرَأَةً فُلَانَةَ ابْنَةَ فُلَانٍ فَجَاءَتْنَا امْرَأَةٌ سَوْدَاءُ فَقَالَتْ إِنِّي أَرْضَعْتُكُمَا وَهِيَ كَافِرَةٌ فَأَعْرَضَ عَنِّي فَأَتَيْتُهُ مِنْ قِبَلِ وَجْهِهِ فَقُلْتُ إِنَّهَا كَاذِبَةٌ فَقَالَ لِي كَيْفَ بِهَا وَقَدْ زَعَمَتْ أَنَّهَا أَرْضَعَتْكُمَا دَعْهَا عَنْكَ ‏","","",""],[15563,15563,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ يَعْنِي ابْنَ أُمَيَّةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ الْحَارِثِ ‏ ‏تَزَوَّجْتُ ‏ ‏ابْنَةَ أَبِي إِيهَابٍ ‏ ‏فَجَاءَتْ امْرَأَةٌ سَوْدَاءُ ‏ ‏يَعْنِي فَذَكَرَتْ أَنَّهَا أَرْضَعَتْكُمَا فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُمْتُ بَيْنَ يَدَيْهِ فَكَلَّمْتُهُ فَأَعْرَضَ عَنِّي فَقُمْتُ عَنْ يَمِينِهِ فَأَعْرَضَ عَنِّي فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّمَا هِيَ سَوْدَاءُ قَالَ فَكَيْفَ وَقَدْ قِيلَ ‏","","",""],[15564,15564,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقْبَةُ بْنُ الْحَارِثِ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنُّعَيْمَانِ ‏ ‏قَدْ شَرِبَ الْخَمْرَ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ فِي الْبَيْتِ فَضَرَبُوهُ بِالْأَيْدِي وَالْجَرِيدِ وَالنِّعَالِ ‏ ‏قَالَ ‏ ‏فَكُنْتُ مِمَّنْ ضَرَبَهُ ‏","","",""],[15565,15565,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعِيدِ بْنِ أَبِي حُسَيْنٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَصْرَ فَلَمَّا سَلَّمَ قَامَ سَرِيعًا فَدَخَلَ عَلَى بَعْضِ نِسَائِهِ ثُمَّ خَرَجَ وَرَأَى مَا فِي ‏ ‏وُجُوهِ الْقَوْمِ مِنْ ‏ ‏تَعَاجُبِهِمْ وَلُبِسَ عَلَيْهِ قَالَ ‏ ‏ذَكَرْتُ وَأَنَا فِي الصَّلَاةِ ‏ ‏تِبْرًا ‏ ‏عِنْدَنَا فَكَرِهْتُ أَنْ يُمْسِيَ ‏ ‏أَوْ يَبِيتَ ‏ ‏عِنْدَنَا فَأَمَرْتُ بِقِسْمَتِهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ صَلَّى الْعَصْرَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[15566,15566,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقْبَةُ بْنُ الْحَارِثِ ‏ ‏أَوْ سَمِعْتُهُ مِنْهُ ‏ ‏أَنَّهُ ‏ ‏تَزَوَّجَ ‏ ‏أُمَّ يَحْيَى ‏ ‏ابْنَةَ ‏ ‏أَبِي إِيهَابٍ ‏ ‏فَجَاءَتْ امْرَأَةٌ سَوْدَاءُ فَقَالَتْ قَدْ أَرْضَعْتُكُمَا فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْرَضَ عَنِّي فَتَنَحَّيْتُ فَذَكَرْتُهُ لَهُ فَقَالَ فَكَيْفَ وَقَدْ زَعَمَتْ أَنْ قَدْ أَرْضَعَتْكُمَا فَنَهَاهُ عَنْهَا ‏","","",""],[15567,15567,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهُ بْنُ عُبَيْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏أَنَّ ‏ ‏عُقْبَةَ بْنَ الْحَارِثِ بْنِ عَامِرٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَوْ سَمِعَهُ مِنْهُ إِنْ لَمْ يَكُنْ خَصَّهُ بِهِ ‏ ‏أَنَّهُ ‏ ‏نَكَحَ ‏ ‏ابْنَةَ أَبِي إِيهَابٍ ‏ ‏فَقَالَتْ أَمَةٌ سَوْدَاءُ قَدْ أَرْضَعْتُكُمَا فَجِئْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَأَعْرَضَ عَنِّي فَجِئْتُ فَذَكَرْتُ لَهُ فَقَالَ فَكَيْفَ وَقَدْ زَعَمَتْ أَنْ قَدْ أَرْضَعَتْكُمَا فَنَهَاهُ عَنْهَا ‏","","",""],[15568,15568,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وُهَيْبُ بْنُ خَالِدٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ الْحَارِثِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ ‏ ‏بِالنُّعَيْمَانِ ‏ ‏أَوْ ‏ ‏ابْنِ النُّعَيْمَانِ ‏ ‏وَهُوَ سَكْرَانُ قَالَ فَاشْتَدَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَرَ مَنْ فِي الْبَيْتِ أَنْ يَضْرِبُوهُ فَضَرَبُوهُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ فَشَقَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَشَقَّةً شَدِيدَةً ‏ ‏قَالَ ‏ ‏عُقْبَةُ ‏ ‏فَكُنْتُ فِيمَنْ ضَرَبَهُ ‏","","",""],[15569,15569,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَوْسٍ الثَّقَفِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى ‏ ‏كِظَامَةَ ‏ ‏قَوْمٍ فَتَوَضَّأَ ‏","","",""],[15570,15570,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْسٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّهُ ‏ ‏كَانَ يُؤْتَى بِنَعْلَيْهِ وَهُوَ ‏ ‏يُصَلِّي فَيَلْبَسُهُمَا وَيَقُولُ إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي نَعْلَيْهِ ‏","","",""],[15571,15571,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَبِي أَوْسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى نَعْلَيْهِ ثُمَّ قَامَ إِلَى الصَّلَاةِ ‏","","",""],[15572,15572,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْسٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي نَعْلَيْهِ ‏ ‏وَاسْتَوْكَفَ ‏ ‏ثَلَاثًا ‏","","",""],[15573,15573,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَوْسًا ‏ ‏يَقُولُ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏وَفْدِ ثَقِيفٍ ‏ ‏فَكُنَّا فِي ‏ ‏قُبَّةٍ ‏ ‏فَقَامَ مَنْ كَانَ فِيهَا غَيْرِي وَغَيْرَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ رَجُلٌ ‏ ‏فَسَارَّهُ ‏ ‏فَقَالَ اذْهَبْ فَاقْتُلْهُ ثُمَّ قَالَ أَلَيْسَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ قَالَ بَلَى وَلَكِنَّهُ يَقُولُهَا ‏ ‏تَعَوُّذًا ‏ ‏فَقَالَ رُدَّهُ ثُمَّ قَالَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا قَالُوهَا حُرِّمَتْ عَلَيَّ دِمَاؤُهُمْ وَأَمْوَالُهُمْ إِلَّا بِحَقِّهَا ‏ ‏فَقُلْتُ ‏ ‏لِشُعْبَةَ ‏ ‏أَلَيْسَ فِي الْحَدِيثِ ثُمَّ قَالَ أَلَيْسَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَظُنُّهَا مَعَهَا وَمَا أَدْرِي ‏","","",""],[15574,15574,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَوْسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ يَوْمُ الْجُمُعَةِ فَغَسَلَ أَحَدُكُمْ رَأْسَهُ وَاغْتَسَلَ ثُمَّ ‏ ‏غَدَا ‏ ‏أَوْ ‏ ‏ابْتَكَرَ ‏ ‏ثُمَّ ‏ ‏دَنَا ‏ ‏فَاسْتَمَعَ وَأَنْصَتَ كَانَ لَهُ بِكُلِّ خُطْوَةٍ خَطَاهَا كَصِيَامِ سَنَةٍ وَقِيَامِ سَنَةٍ ‏","","",""],[15575,15575,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ الْجُعْفِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمُ الْجُمُعَةِ فِيهِ خُلِقَ ‏ ‏آدَمُ ‏ ‏وَفِيهِ قُبِضَ وَفِيهِ النَّفْخَةُ وَفِيهِ ‏ ‏الصَّعْقَةُ ‏ ‏فَأَكْثِرُوا عَلَيَّ مِنْ الصَّلَاةِ فِيهِ فَإِنَّ صَلَاتَكُمْ مَعْرُوضَةٌ عَلَيَّ فَقَالُوا يَا رَسُولَ اللَّهِ وَكَيْفَ تُعْرَضُ عَلَيْكَ صَلَاتُنَا وَقَدْ ‏ ‏أَرِمْتَ ‏ ‏يَعْنِي وَقَدْ بَلِيتَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ حَرَّمَ عَلَى الْأَرْضِ أَنْ تَأْكُلَ أَجْسَادَ الْأَنْبِيَاءِ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهِمْ ‏","","",""],[15576,15576,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ السَّهْمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ أَبِي صَغِيرَةَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ أَوْسٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَوْسًا ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏إِنَّا لَقُعُودٌ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الصُّفَّةِ ‏ ‏وَهُوَ يَقُصُّ عَلَيْنَا وَيُذَكِّرُنَا إِذْ جَاءَ رَجُلٌ ‏ ‏فَسَارَّهُ ‏ ‏فَقَالَ اذْهَبُوا فَاقْتُلُوهُ قَالَ فَلَمَّا وَلَّى الرَّجُلُ دَعَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَيَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ قَالَ الرَّجُلُ نَعَمْ نَعَمْ يَا رَسُولَ اللَّهِ فَقَالَ اذْهَبُوا فَخَلُّوا سَبِيلَهُ فَإِنَّمَا ‏ ‏أُمِرْتُ أَنْ ‏ ‏أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا فَعَلُوا ذَلِكَ حُرِّمَتْ عَلَيَّ دِمَاؤُهُمْ وَأَمْوَالُهُمْ إِلَّا بِحَقِّهَا ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الْأَنْصَارِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو يُونُسَ حَاتِمُ بْنُ أَبِي صَغِيرَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏النُّعْمَانُ بْنُ سَالِمٍ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ أَوْسٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْسٍ ‏ ‏قَالَ ‏ ‏إِنَّا لَقُعُودٌ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُنَا ‏ ‏وَيُوصِينَا إِذْ أَتَاهُ رَجُلٌ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[15577,15577,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَبِي أَوْسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبِي ‏ ‏يَوْمًا ‏ ‏تَوَضَّأَ فَمَسَحَ النَّعْلَيْنِ فَقُلْتُ لَهُ أَتَمْسَحُ عَلَيْهِمَا فَقَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ ‏","","",""],[15578,15578,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ الطَّائِفِيُّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ أَوْسٍ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَوْسِ بْنِ حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي الْوَفْدِ الَّذِينَ أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمُوا مِنْ ‏ ‏ثَقِيفٍ ‏ ‏مِنْ ‏ ‏بَنِي مَالِكٍ ‏ ‏أَنْزَلَنَا فِي ‏ ‏قُبَّةٍ ‏ ‏لَهُ فَكَانَ ‏ ‏يَخْتَلِفُ ‏ ‏إِلَيْنَا بَيْنَ بُيُوتِهِ وَبَيْنَ الْمَسْجِدِ فَإِذَا صَلَّى الْعِشَاءَ الْآخِرَةَ انْصَرَفَ إِلَيْنَا وَلَا نَبْرَحُ حَتَّى يُحَدِّثَنَا ‏ ‏وَيَشْتَكِي ‏ ‏قُرَيْشًا ‏ ‏وَيَشْتَكِي أَهْلَ ‏ ‏مَكَّةَ ‏ ‏ثُمَّ يَقُولُ ‏ ‏لَا سَوَاءَ كُنَّا ‏ ‏بِمَكَّةَ ‏ ‏مُسْتَذَلِّينَ وَمُسْتَضْعَفِينَ فَلَمَّا خَرَجْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏كَانَتْ ‏ ‏سِجَالُ ‏ ‏الْحَرْبِ عَلَيْنَا وَلَنَا فَمَكَثَ عَنَّا لَيْلَةً لَمْ يَأْتِنَا حَتَّى طَالَ ذَلِكَ عَلَيْنَا بَعْدَ الْعِشَاءِ قَالَ قُلْنَا مَا أَمْكَثَكَ عَنَّا يَا رَسُولَ اللَّهِ قَالَ طَرَأَ عَلَيَّ حِزْبٌ مِنْ الْقُرْآنِ فَأَرَدْتُ أَنْ لَا أَخْرُجَ حَتَّى أَقْضِيَهُ قَالَ فَسَأَلْنَا ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَصْبَحْنَا قَالَ قُلْنَا كَيْفَ تُحَزِّبُونَ الْقُرْآنَ قَالُوا نُحَزِّبُهُ ثَلَاثَ سُوَرٍ وَخَمْسَ سُوَرٍ وَسَبْعَ سُوَرٍ وَتِسْعَ سُوَرٍ وَإِحْدَى عَشْرَةَ سُورَةً وَثَلَاثَ عَشْرَةَ سُورَةً وَحِزْبَ ‏ ‏الْمُفَصَّلِ ‏ ‏مِنْ ‏ ‏قَافْ حَتَّى يُخْتَمَ ‏","","",""],[15579,15579,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْسٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي نَعْلَيْهِ ‏","","",""],[15580,15580,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَبِي أَوْسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى نَعْلَيْهِ ‏","","",""],[15581,15581,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏النُّعْمَانُ بْنُ سَالِمٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏جَدُّهُ ‏ ‏أَوْسُ بْنُ أَبِي أَوْسٍ ‏ ‏كَانَ ‏ ‏يُصَلِّي وَيُومِئُ إِلَى نَعْلَيْهِ وَهُوَ فِي الصَّلَاةِ فَيَأْخُذُهُمَا فَيَنْتَعِلُهُمَا وَيُصَلِّي فِيهِمَا وَيَقُولُ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي نَعْلَيْهِ ‏","","",""],[15582,15582,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْسٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَوْسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ‏ ‏وَاسْتَوْكَفَ ‏ ‏ثَلَاثًا أَيْ غَسَلَ كَفَّيْهِ ‏","","",""],[15583,15583,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ بْنُ الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْسٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَوْسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ‏ ‏فَاسْتَوْكَفَ ‏ ‏ثَلَاثًا ‏ ‏يَعْنِي غَسَلَ يَدَيْهِ ثَلَاثًا ‏ ‏فَقُلْتُ ‏ ‏لِشُعْبَةَ ‏ ‏أَدْخَلَهُمَا فِي الْإِنَاءِ أَوْ غَسَلَهُمَا خَارِجًا ‏ ‏قَالَ ‏ ‏لَا أَدْرِي ‏","","",""],[15584,15584,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ الْجُعْفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بِهِ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ غَسَّلَ وَاغْتَسَلَ ‏ ‏وَغَدَا ‏ ‏وَابْتَكَرَ ‏ ‏فَدَنَا ‏ ‏وَأَنْصَتَ وَلَمْ ‏ ‏يَلْغُ ‏ ‏كَانَ لَهُ بِكُلِّ خُطْوَةٍ كَأَجْرِ سَنَةٍ صِيَامِهَا وَقِيَامِهَا ‏","","",""],[15585,15585,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَوْسٍ الثَّقَفِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ غَسَّلَ وَاغْتَسَلَ يَوْمَ الْجُمُعَةِ وَبَكَّرَ ‏ ‏وَابْتَكَرَ ‏ ‏وَمَشَى وَلَمْ يَرْكَبْ ‏ ‏فَدَنَا ‏ ‏مِنْ الْإِمَامِ فَاسْتَمَعَ وَلَمْ ‏ ‏يَلْغُ ‏ ‏كَانَ لَهُ بِكُلِّ خُطْوَةٍ عَمَلُ سَنَةٍ أَجْرُ صِيَامِهَا وَقِيَامِهَا ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَسَّانُ بْنُ عَطِيَّةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْأَشْعَثِ الصَّنْعَانِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَوْسُ بْنُ أَوْسٍ الثَّقَفِيُّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ ثُمَّ ‏ ‏غَدَا ‏ ‏وَابْتَكَرَ ‏","","",""],[15586,15586,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ الدِّمَشْقِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْأَشْعَثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَوْسُ بْنُ أَوْسٍ الثَّقَفِيُّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذَكَرَ الْجُمُعَةَ فَقَالَ ‏ ‏مَنْ غَسَّلَ وَاغْتَسَلَ ثُمَّ ‏ ‏غَدَا ‏ ‏وَابْتَكَرَ ‏ ‏وَخَرَجَ يَمْشِي وَلَمْ يَرْكَبْ ثُمَّ ‏ ‏دَنَا ‏ ‏مِنْ الْإِمَامِ فَأَنْصَتَ وَلَمْ ‏ ‏يَلْغُ ‏ ‏كَانَ لَهُ كَأَجْرِ سَنَةٍ صِيَامِهَا وَقِيَامِهَا ‏ ‏قَالَ ‏ ‏وَزَعَمَ ‏ ‏يَحْيَى بْنُ الْحَارِثِ ‏ ‏أَنَّهُ حَفِظَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَهُ بِكُلِّ خُطْوَةٍ كَأَجْرِ سَنَةٍ صِيَامِهَا وَقِيَامِهَا ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَلَمْ أَسْمَعْهُ يَقُولُ مَشَى وَلَمْ يَرْكَبْ ‏","","",""],[15587,15587,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ دَاوُدَ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَوْسٍ الثَّقَفِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اغْتَسَلَ يَوْمَ الْجُمُعَةِ وَغَسَّلَ ثُمَّ ‏ ‏ابْتَكَرَ ‏ ‏وَغَدَا ‏ ‏إِلَى الْمَسْجِدِ ثُمَّ جَلَسَ قَرِيبًا مِنْ الْإِمَامِ حَتَّى يُنْصِتَ كَانَ لَهُ بِكُلِّ خُطْوَةٍ خَطَاهَا عَمَلُ سَنَةٍ صِيَامُهَا وَقِيَامُهَا ‏","","",""],[15588,15588,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏كَانَ جَدِّي ‏ ‏أَوْسٌ ‏ ‏أَحْيَانًا ‏ ‏يُصَلِّي فَيُشِيرُ إِلَيَّ وَهُوَ فِي الصَّلَاةِ فَأُعْطِيهِ نَعْلَيْهِ وَيَقُولُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي نَعْلَيْهِ ‏","","",""],[15589,15589,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَوْسٍ الثَّقَفِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ غَسَّلَ وَاغْتَسَلَ ثُمَّ ‏ ‏غَدَا ‏ ‏فَابْتَكَرَ ‏ ‏وَجَلَسَ مِنْ الْإِمَامِ قَرِيبًا فَاسْتَمَعَ وَأَنْصَتَ كَانَ بِكُلِّ خَطْوَةٍ أَجْرُ سَنَةٍ صِيَامُهَا وَقِيَامُهَا ‏","","",""],[15590,15590,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏النُّعْمَانُ بْنُ سَالِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏فُلَانًا ‏ ‏أَوْسٌ ‏ ‏جَدُّهُ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏جَدِّي ‏ ‏يَقُولُ لِي وَهُوَ فِي الصَّلَاةِ يُومِئُ إِلَيَّ نَاوِلْنِي النَّعْلَيْنِ فَأُنَاوِلُهُمَا إِيَّاهُ فَيَلْبَسُهُمَا وَيُصَلِّي فِيهِمَا وَيَقُولُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي نَعْلَيْهِ ‏","","",""],[15591,15591,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ أَوْسٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَدِّهِ ‏ ‏أَوْسِ بْنِ أَبِي أَوْسٍ ‏ ‏أَنَّهُ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏فَاسْتَوْكَفَ ‏ ‏ثَلَاثًا ‏ ‏قَالَ ‏ ‏قُلْتُ أَيُّ شَيْءٍ ‏ ‏اسْتَوْكَفَ ‏ ‏ثَلَاثًا ‏ ‏قَالَ ‏ ‏غَسَلَ يَدَيْهِ ثَلَاثًا ‏","","",""],[15592,15592,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَبِي أَوْسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏أَبِي ‏ ‏عَلَى مَاءٍ مِنْ مِيَاهِ ‏ ‏الْعَرَبِ ‏ ‏فَتَوَضَّأَ وَمَسَحَ عَلَى نَعْلَيْهِ فَقِيلَ لَهُ فَقَالَ مَا أَزِيدُكَ عَلَى مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ ‏","","",""],[15593,15593,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ عُدُسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرُّؤْيَا عَلَى رِجْلِ طَائِرٍ مَا لَمْ ‏ ‏تُعَبَّرْ ‏ ‏فَإِذَا ‏ ‏عُبِّرَتْ ‏ ‏وَقَعَتْ قَالَ وَالرُّؤْيَا جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ قَالَ وَأَحْسِبُهُ قَالَ لَا يَقُصُّهَا إِلَّا عَلَى وَادٍّ أَوْ ذِي رَأْيٍ ‏","","",""],[15594,15594,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ عُدُسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرُّؤْيَا مُعَلَّقَةٌ بِرِجْلِ طَائِرٍ مَا لَمْ يُحَدِّثْ بِهَا صَاحِبُهَا فَإِذَا حَدَّثَ بِهَا وَقَعَتْ وَلَا تُحَدِّثُوا بِهَا إِلَّا عَالِمًا أَوْ نَاصِحًا أَوْ ‏ ‏لَبِيبًا ‏ ‏وَالرُّؤْيَا الصَّالِحَةُ جُزْءٌ مِنْ أَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏","","",""],[15595,15595,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ الْعُقَيْلِيِّ ‏ ‏أَنَّهُ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ أَبِي شَيْخٌ كَبِيرٌ لَا يَسْتَطِيعُ الْحَجَّ وَلَا الْعُمْرَةَ وَلَا ‏ ‏الظَّعْنَ ‏ ‏قَالَ ‏ ‏حُجَّ عَنْ أَبِيكَ وَاعْتَمِرْ ‏","","",""],[15596,15596,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ الْعُقَيْلِيِّ ‏ ‏أَنَّهُ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ أَبِي شَيْخٌ كَبِيرٌ لَا يَسْتَطِيعُ الْحَجَّ وَلَا الْعُمْرَةَ وَلَا ‏ ‏الظَّعْنَ ‏ ‏قَالَ ‏ ‏حُجَّ عَنْ أَبِيكَ وَاعْتَمِرْ ‏","","",""],[15597,15597,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ عُدُسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَكُلُّنَا يَرَى اللَّهَ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ وَمَا آيَةُ ذَلِكَ فِي خَلْقِهِ قَالَ يَا ‏ ‏أَبَا رَزِينٍ ‏ ‏أَلَيْسَ كُلُّكُمْ يَرَى الْقَمَرَ مُخْلِيًا بِهِ قَالَ قُلْتُ بَلَى يَا رَسُولَ اللَّهِ قَالَ فَاللَّهُ أَعْظَمُ ‏","","",""],[15598,15598,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ عُدُسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحِكَ رَبُّنَا مِنْ قُنُوطِ عَبْدِهِ وَقُرْبِ غَيْرِهِ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أَوَيَضْحَكُ الرَّبُّ عَزَّ وَجَلَّ قَالَ نَعَمْ قَالَ لَنْ نَعْدَمَ مِنْ رَبٍّ يَضْحَكُ خَيْرًا ‏","","",""],[15599,15599,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ عُدُسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَيْنَ كَانَ رَبُّنَا عَزَّ وَجَلَّ قَبْلَ أَنْ يَخْلُقَ خَلْقَهُ قَالَ ‏ ‏كَانَ فِي ‏ ‏عَمَاءٍ ‏ ‏مَا تَحْتَهُ هَوَاءٌ وَمَا فَوْقَهُ هَوَاءٌ ثُمَّ خَلَقَ عَرْشَهُ عَلَى الْمَاءِ ‏","","",""],[15600,15600,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ عُدُسٍ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَيْنَ أُمِّي قَالَ أُمُّكَ فِي النَّارِ قَالَ قُلْتُ فَأَيْنَ مَنْ مَضَى مِنْ أَهْلِكَ قَالَ ‏ ‏أَمَا ‏ ‏تَرْضَى أَنْ تَكُونَ أُمُّكَ مَعَ أُمِّي ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏الصَّوَابُ ‏ ‏حُدُسٌ ‏","","",""]];
